 35→// mustInitBareRepo creates a bare git repo for testing.
 36→func mustInitBareRepo(t *testing.T) *git.Repository {
 37→	t.Helper()
 38→	repo, err := git.PlainInit(t.TempDir(), true)
 39→	if err != nil {
 40→		t.Fatalf("failed to init bare repo: %v", err)
 41→	}
 42→	return repo
 43→}
