 45→// mustStoreTree stores a tree and fatals on error.
 46→func mustStoreTree(t *testing.T, repo *git.Repository, entries []object.TreeEntry) plumbing.Hash {
 47→	t.Helper()
 48→	hash, err := storeTree(repo, entries)
 49→	if err != nil {
 50→		t.Fatalf("storeTree() error = %v", err)
 51→	}
 52→	return hash
 53→}
 54→
 55→// mustTreeObject reads a tree object and fatals on error.
 56→func mustTreeObject(t *testing.T, repo *git.Repository, hash plumbing.Hash) *object.Tree {
 57→	t.Helper()
 58→	tree, err := repo.TreeObject(hash)
 59→	if err != nil {
 60→		t.Fatalf("failed to read tree %s: %v", hash, err)
 61→	}
 62→	return tree
 63→}
 64→
 65→// flattenTreeHelper reads a tree recursively and returns all entries as path->hash.
 66→func flattenTreeHelper(t *testing.T, repo *git.Repository, treeHash plumbing.Hash, prefix string) map[string]plumbing.Hash {
 67→	t.Helper()
 68→	result := make(map[string]plumbing.Hash)
 69→	tree := mustTreeObject(t, repo, treeHash)
 70→	for _, entry := range tree.Entries {
 71→		fullPath := entry.Name
 72→		if prefix != "" {
 73→			fullPath = prefix + "/" + entry.Name
 74→		}
 75→		if entry.Mode == filemode.Dir {
 76→			sub := flattenTreeHelper(t, repo, entry.Hash, fullPath)
 77→			for k, v := range sub {
 78→				result[k] = v
 79→			}
 80→		} else {
 81→			result[fullPath] = entry.Hash
 82→		}
 83→	}
 84→	return result
 85→}
