 87→func TestSplitFirstSegment(t *testing.T) {
 88→	t.Parallel()
 89→
 90→	tests := []struct {
 91→		path      string
 92→		wantFirst string
 93→		wantRest  string
 94→	}{
 95→		{"file.txt", "file.txt", ""},
 96→		{"a/b", "a", "b"},
 97→		{"a/b/c", "a", "b/c"},
 98→		{"dir/sub/file.txt", "dir", "sub/file.txt"},
 99→	}
100→
101→	for _, tt := range tests {
102→		first, rest := splitFirstSegment(tt.path)
103→		if first != tt.wantFirst || rest != tt.wantRest {
104→			t.Errorf("splitFirstSegment(%q) = (%q, %q), want (%q, %q)",
105→				tt.path, first, rest, tt.wantFirst, tt.wantRest)
106→		}
107→	}
108→}
