110→func TestStoreTree_RoundTrip(t *testing.T) {
111→	t.Parallel()
112→	repo := mustInitBareRepo(t)
113→
114→	blobHash := storeBlob(t, repo, "hello")
115→	entries := []object.TreeEntry{
116→		{Name: "file.txt", Mode: filemode.Regular, Hash: blobHash},
117→	}
118→
119→	hash, err := storeTree(repo, entries)
120→	if err != nil {
121→		t.Fatalf("storeTree() error = %v", err)
122→	}
123→	if hash == plumbing.ZeroHash {
124→		t.Fatal("storeTree() returned zero hash")
125→	}
126→
127→	// Read it back
128→	tree := mustTreeObject(t, repo, hash)
129→	if len(tree.Entries) != 1 {
130→		t.Fatalf("expected 1 entry, got %d", len(tree.Entries))
131→	}
132→	if tree.Entries[0].Name != "file.txt" {
133→		t.Errorf("expected file.txt, got %s", tree.Entries[0].Name)
134→	}
135→	if tree.Entries[0].Hash != blobHash {
136→		t.Errorf("hash mismatch: got %s, want %s", tree.Entries[0].Hash, blobHash)
137→	}
138→}
