140→func TestUpdateSubtree_CreateFromEmpty(t *testing.T) {
141→	t.Parallel()
142→	repo := mustInitBareRepo(t)
143→
144→	blob1 := storeBlob(t, repo, "content1")
145→	blob2 := storeBlob(t, repo, "content2")
146→
147→	newEntries := []object.TreeEntry{
148→		{Name: "metadata.json", Mode: filemode.Regular, Hash: blob1},
149→		{Name: "full.jsonl", Mode: filemode.Regular, Hash: blob2},
150→	}
151→
152→	// Create tree at path a3/b2c4d5e6f7/ from empty root
153→	hash, err := UpdateSubtree(repo, plumbing.ZeroHash, []string{"a3", "b2c4d5e6f7"}, newEntries, UpdateSubtreeOptions{})
154→	if err != nil {
155→		t.Fatalf("UpdateSubtree() error = %v", err)
156→	}
157→
158→	// Verify structure: root -> a3/ -> b2c4d5e6f7/ -> {metadata.json, full.jsonl}
159→	files := flattenTreeHelper(t, repo, hash, "")
160→	if len(files) != 2 {
161→		t.Fatalf("expected 2 files, got %d: %v", len(files), files)
162→	}
163→	if files["a3/b2c4d5e6f7/metadata.json"] != blob1 {
164→		t.Error("metadata.json not found or wrong hash")
165→	}
166→	if files["a3/b2c4d5e6f7/full.jsonl"] != blob2 {
167→		t.Error("full.jsonl not found or wrong hash")
168→	}
169→}
