171→func TestUpdateSubtree_PreservesSiblings(t *testing.T) {
172→	t.Parallel()
173→	repo := mustInitBareRepo(t)
174→
175→	blobA := storeBlob(t, repo, "existing-a")
176→	blobB := storeBlob(t, repo, "existing-b")
177→	blobNew := storeBlob(t, repo, "new-content")
178→
179→	// Build an initial tree:
180→	// a3/
181→	//   existing1/ -> {file.txt: blobA}
182→	//   existing2/ -> {file.txt: blobB}
183→	innerTree1 := mustStoreTree(t, repo, []object.TreeEntry{
184→		{Name: "file.txt", Mode: filemode.Regular, Hash: blobA},
185→	})
186→	innerTree2 := mustStoreTree(t, repo, []object.TreeEntry{
187→		{Name: "file.txt", Mode: filemode.Regular, Hash: blobB},
188→	})
189→	shardTree := mustStoreTree(t, repo, []object.TreeEntry{
190→		{Name: "existing1", Mode: filemode.Dir, Hash: innerTree1},
191→		{Name: "existing2", Mode: filemode.Dir, Hash: innerTree2},
192→	})
193→	rootTree := mustStoreTree(t, repo, []object.TreeEntry{
194→		{Name: "a3", Mode: filemode.Dir, Hash: shardTree},
195→	})
196→
197→	// Now add a new subtree at a3/newcheckpoint/
198→	newEntries := []object.TreeEntry{
199→		{Name: "data.json", Mode: filemode.Regular, Hash: blobNew},
200→	}
201→	newRoot, err := UpdateSubtree(repo, rootTree, []string{"a3", "newcheckpoint"}, newEntries, UpdateSubtreeOptions{})
202→	if err != nil {
203→		t.Fatalf("UpdateSubtree() error = %v", err)
204→	}
205→
206→	files := flattenTreeHelper(t, repo, newRoot, "")
207→
208→	// Should have 3 files now: 2 existing + 1 new
209→	if len(files) != 3 {
210→		t.Fatalf("expected 3 files, got %d: %v", len(files), files)
211→	}
212→	if files["a3/existing1/file.txt"] != blobA {
213→		t.Error("existing1/file.txt lost or wrong hash")
214→	}
215→	if files["a3/existing2/file.txt"] != blobB {
216→		t.Error("existing2/file.txt lost or wrong hash")
217→	}
218→	if files["a3/newcheckpoint/data.json"] != blobNew {
219→		t.Error("newcheckpoint/data.json not found")
220→	}
221→
222→	// Verify sibling subtrees weren't re-created (same hash)
223→	root := mustTreeObject(t, repo, newRoot)
224→	for _, e := range root.Entries {
225→		if e.Name == "a3" {
226→			a3Tree := mustTreeObject(t, repo, e.Hash)
227→			for _, sub := range a3Tree.Entries {
228→				if sub.Name == "existing1" && sub.Hash != innerTree1 {
229→					t.Error("existing1 subtree hash changed — should be preserved")
230→				}
231→				if sub.Name == "existing2" && sub.Hash != innerTree2 {
232→					t.Error("existing2 subtree hash changed — should be preserved")
233→				}
234→			}
235→		}
236→	}
237→}
