281→func TestUpdateSubtree_MergeKeepExisting(t *testing.T) {
282→	t.Parallel()
283→	repo := mustInitBareRepo(t)
284→
285→	blobExisting := storeBlob(t, repo, "existing")
286→	blobNew := storeBlob(t, repo, "new")
