686→// TestUpdateSubtree_EquivalenceWithFlattenRebuild verifies that UpdateSubtree
687→// produces the same result as the old FlattenTree + modify + BuildTreeFromEntries approach.
688→func TestUpdateSubtree_EquivalenceWithFlattenRebuild(t *testing.T) {
689→	t.Parallel()
690→	repo := mustInitBareRepo(t)
691→
692→	// Build a realistic sharded tree with multiple checkpoints
693→	blobs := make([]plumbing.Hash, 5)
694→	for i := range blobs {
695→		blobs[i] = storeBlob(t, repo, fmt.Sprintf("content-%d", i))
696→	}
697→
698→	// Build: a3/ckpt1/{meta.json, full.jsonl}, a3/ckpt2/{meta.json}, b7/ckpt3/{meta.json}
699→	ckpt1 := mustStoreTree(t, repo, []object.TreeEntry{
700→		{Name: "full.jsonl", Mode: filemode.Regular, Hash: blobs[1]},
701→		{Name: "meta.json", Mode: filemode.Regular, Hash: blobs[0]},
702→	})
703→	ckpt2 := mustStoreTree(t, repo, []object.TreeEntry{
704→		{Name: "meta.json", Mode: filemode.Regular, Hash: blobs[2]},
705→	})
706→	ckpt3 := mustStoreTree(t, repo, []object.TreeEntry{
707→		{Name: "meta.json", Mode: filemode.Regular, Hash: blobs[3]},
708→	})
709→	shardA3 := mustStoreTree(t, repo, []object.TreeEntry{
710→		{Name: "ckpt1", Mode: filemode.Dir, Hash: ckpt1},
711→		{Name: "ckpt2", Mode: filemode.Dir, Hash: ckpt2},
712→	})
713→	shardB7 := mustStoreTree(t, repo, []object.TreeEntry{
714→		{Name: "ckpt3", Mode: filemode.Dir, Hash: ckpt3},
715→	})
716→	rootTree := mustStoreTree(t, repo, []object.TreeEntry{
717→		{Name: "a3", Mode: filemode.Dir, Hash: shardA3},
718→		{Name: "b7", Mode: filemode.Dir, Hash: shardB7},
719→	})
720→
721→	// Now add a new checkpoint at a3/newckpt/ using tree surgery
722→	newBlob := storeBlob(t, repo, "new-checkpoint")
723→	surgeryResult, err := UpdateSubtree(repo, rootTree, []string{"a3", "newckpt"}, []object.TreeEntry{
724→		{Name: "meta.json", Mode: filemode.Regular, Hash: newBlob},
725→	}, UpdateSubtreeOptions{})
726→	if err != nil {
727→		t.Fatalf("UpdateSubtree() error = %v", err)
728→	}
729→
730→	// Do the same with FlattenTree + BuildTreeFromEntries
731→	tree := mustTreeObject(t, repo, rootTree)
732→	flatEntries := make(map[string]object.TreeEntry)
733→	if err := FlattenTree(repo, tree, "", flatEntries); err != nil {
734→		t.Fatalf("FlattenTree() error = %v", err)
735→	}
736→	flatEntries["a3/newckpt/meta.json"] = object.TreeEntry{
737→		Name: "meta.json",
738→		Mode: filemode.Regular,
739→		Hash: newBlob,
740→	}
741→	flatResult, err := BuildTreeFromEntries(repo, flatEntries)
742→	if err != nil {
743→		t.Fatalf("BuildTreeFromEntries() error = %v", err)
744→	}
745→
746→	// Both approaches should produce the exact same tree hash
747→	if surgeryResult != flatResult {
748→		t.Errorf("tree surgery result (%s) != flatten+rebuild result (%s)", surgeryResult, flatResult)
749→
750→		// Debug: show both trees
751→		surgeryFiles := flattenTreeHelper(t, repo, surgeryResult, "")
752→		flatFiles := flattenTreeHelper(t, repo, flatResult, "")
753→		t.Logf("Surgery files: %v", surgeryFiles)
754→		t.Logf("Flat files: %v", flatFiles)
755→	}
756→}
