1028→// sortTreeEntries sorts tree entries in git's required order.
1029→// Git sorts tree entries by name, with directories having a trailing /
1030→func sortTreeEntries(entries []object.TreeEntry) {
1031→	sort.Slice(entries, func(i, j int) bool {
1032→		nameI := entries[i].Name
1033→		nameJ := entries[j].Name
1034→		if entries[i].Mode == filemode.Dir {
1035→			nameI += "/"
1036→		}
1037→		if entries[j].Mode == filemode.Dir {
1038→			nameJ += "/"
1039→		}
1040→		return nameI < nameJ
1041→	})
1042→}
