588→// calculateTokenUsage calculates token usage from raw transcript data.
589→// startOffset is the line number (Claude Code) or message index (Gemini CLI)
590→// where the current checkpoint began, allowing calculation for only the portion
591→// of the transcript since the last checkpoint.
592→func calculateTokenUsage(agentType agent.AgentType, data []byte, startOffset int) *agent.TokenUsage {
593→	// No token usage information from Cursor yet
594→	if agentType == agent.AgentTypeCursor {
595→		return nil
596→	}
597→
598→	if len(data) == 0 {
599→		return &agent.TokenUsage{}
600→	}
601→
602→	// OpenCode uses JSONL with token info on assistant messages (different schema from Claude Code)
603→	if agentType == agent.AgentTypeOpenCode {
604→		return opencode.CalculateTokenUsageFromBytes(data, startOffset)
605→	}
606→
607→	// Try Gemini format first if agentType is Gemini, or as fallback if Unknown
608→	if agentType == agent.AgentTypeGemini || agentType == agent.AgentTypeUnknown {
609→		// Attempt to parse as Gemini JSON
610→		transcript, err := geminicli.ParseTranscript(data)
611→		if err == nil && transcript != nil && len(transcript.Messages) > 0 {
612→			return geminicli.CalculateTokenUsage(data, startOffset)
613→		}
614→		// If agentType is explicitly Gemini but parsing failed, return empty usage
615→		if agentType == agent.AgentTypeGemini {
616→			return &agent.TokenUsage{}
617→		}
618→		// Otherwise fall through to JSONL parsing for Unknown type
619→	}
620→
621→	// Claude Code and other JSONL-based agents
622→	lines, err := transcript.ParseFromBytes(data)
623→	if err != nil || len(lines) == 0 {
624→		return &agent.TokenUsage{}
625→	}
626→	// Slice transcript lines to only include checkpoint portion
627→	if startOffset > 0 && startOffset < len(lines) {
628→		lines = lines[startOffset:]
629→	}
630→	return claudecode.CalculateTokenUsage(lines)
631→}
