633→// extractUserPromptsFromLines extracts user prompts from JSONL transcript lines.
634→// IDE-injected context tags (like <ide_opened_file>) are stripped from the results.
635→func extractUserPromptsFromLines(lines []string) []string {
636→	var prompts []string
637→	for _, line := range lines {
638→		line = strings.TrimSpace(line)
639→		if line == "" {
640→			continue
641→		}
642→
643→		var entry map[string]interface{}
644→		if err := json.Unmarshal([]byte(line), &entry); err != nil {
645→			continue
646→		}
647→
648→		// Check for user message:
649→		// - Claude Code uses "type": "human" or "type": "user"
650→		// - Cursor uses "role": "user"
651→		msgType, _ := entry["type"].(string) //nolint:errcheck // type assertion on interface{} from JSON
652→		msgRole, _ := entry["role"].(string) //nolint:errcheck // type assertion on interface{} from JSON
653→		isUser := msgType == "human" || msgType == "user" || msgRole == "user"
654→		if !isUser {
