 18→	"github.com/entireio/cli/cmd/entire/cli/transcript"
 19→)
 20→
 21→//nolint:gochecknoinits // Agent self-registration is the intended pattern
 22→func init() {
 23→	agent.Register(agent.AgentNameClaudeCode, NewClaudeCodeAgent)
 24→}
 25→
 26→// ClaudeCodeAgent implements the Agent interface for Claude Code.
 27→//
 28→//nolint:revive // ClaudeCodeAgent is clearer than Agent in this context
 29→type ClaudeCodeAgent struct{}
 30→
 31→// NewClaudeCodeAgent creates a new Claude Code agent instance.
 32→func NewClaudeCodeAgent() agent.Agent {
 33→	return &ClaudeCodeAgent{}
 34→}
 35→
 36→// Name returns the agent registry key.
 37→func (c *ClaudeCodeAgent) Name() agent.AgentName {
 38→	return agent.AgentNameClaudeCode
 39→}
 40→
 41→// Type returns the agent type identifier.
 42→func (c *ClaudeCodeAgent) Type() agent.AgentType {
 43→	return agent.AgentTypeClaudeCode
 44→}
 45→
 46→// Description returns a human-readable description.
 47→func (c *ClaudeCodeAgent) Description() string {
 48→	return "Claude Code - Anthropic's CLI coding assistant"
 49→}
 50→
 51→func (c *ClaudeCodeAgent) IsPreview() bool { return false }
 52→
 53→// DetectPresence checks if Claude Code is configured in the repository.
 54→func (c *ClaudeCodeAgent) DetectPresence(ctx context.Context) (bool, error) {
 55→	// Get worktree root to check for .claude directory
 56→	// This is needed because the CLI may be run from a subdirectory
 57→	repoRoot, err := paths.WorktreeRoot(ctx)
 58→	if err != nil {
 59→		// Not in a git repo, fall back to CWD-relative check
 60→		repoRoot = "."
 61→	}
 62→
 63→	// Check for .claude directory
 64→	claudeDir := filepath.Join(repoRoot, ".claude")
 65→	if _, err := os.Stat(claudeDir); err == nil {
 66→		return true, nil
 67→	}
 68→	// Check for .claude/settings.json
 69→	settingsFile := filepath.Join(repoRoot, ".claude", "settings.json")
 70→	if _, err := os.Stat(settingsFile); err == nil {
 71→		return true, nil
 72→	}
 73→	return false, nil
 74→}
 75→
 76→// GetSessionID extracts the session ID from hook input.
 77→func (c *ClaudeCodeAgent) GetSessionID(input *agent.HookInput) string {
 78→	return input.SessionID
 79→}
 80→
 81→// ResolveSessionFile returns the path to a Claude session file.
 82→// Claude names files directly as <id>.jsonl.
 83→func (c *ClaudeCodeAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
 84→	return filepath.Join(sessionDir, agentSessionID+".jsonl")
 85→}
 86→
 87→// ProtectedDirs returns directories that Claude uses for config/state.
 88→func (c *ClaudeCodeAgent) ProtectedDirs() []string { return []string{".claude"} }
 89→
 90→// GetSessionDir returns the directory where Claude stores session transcripts.
 91→func (c *ClaudeCodeAgent) GetSessionDir(repoPath string) (string, error) {
 92→	// Check for test environment override
 93→	if override := os.Getenv("ENTIRE_TEST_CLAUDE_PROJECT_DIR"); override != "" {
 94→		return override, nil
 95→	}
 96→
 97→	homeDir, err := os.UserHomeDir()
 98→	if err != nil {
 99→		return "", fmt.Errorf("failed to get home directory: %w", err)
100→	}
101→
102→	projectDir := SanitizePathForClaude(repoPath)
103→	return filepath.Join(homeDir, ".claude", "projects", projectDir), nil
104→}
105→
106→// ReadSession reads a session from Claude's storage (JSONL transcript file).
107→// The session data is stored in NativeData as raw JSONL bytes.
108→// ModifiedFiles is computed by parsing the transcript.
109→func (c *ClaudeCodeAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
110→	if input.SessionRef == "" {
111→		return nil, errors.New("session reference (transcript path) is required")
112→	}
113→
114→	// Read the raw JSONL file
115→	data, err := os.ReadFile(input.SessionRef)
116→	if err != nil {
117→		return nil, fmt.Errorf("failed to read transcript: %w", err)
118→	}
119→
120→	// Parse to extract computed fields
121→	lines, err := transcript.ParseFromBytes(data)
122→	if err != nil {
123→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
124→	}
125→
126→	return &agent.AgentSession{
127→		SessionID:     input.SessionID,
128→		AgentName:     c.Name(),
129→		SessionRef:    input.SessionRef,
130→		StartTime:     time.Now(),
131→		NativeData:    data,
132→		ModifiedFiles: ExtractModifiedFiles(lines),
133→	}, nil
134→}
135→
136→// WriteSession writes a session to Claude's storage (JSONL transcript file).
137→// Uses the NativeData field which contains raw JSONL bytes.
138→// The session must have been created by Claude Code (AgentName check).
139→func (c *ClaudeCodeAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
140→	if session == nil {
141→		return errors.New("session is nil")
142→	}
143→
144→	// Verify this session belongs to Claude Code
145→	if session.AgentName != "" && session.AgentName != c.Name() {
146→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
147→	}
148→
149→	if session.SessionRef == "" {
150→		return errors.New("session reference (transcript path) is required")
151→	}
152→
153→	if len(session.NativeData) == 0 {
154→		return errors.New("session has no native data to write")
155→	}
156→
157→	// Write the raw JSONL data
158→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
159→		return fmt.Errorf("failed to write transcript: %w", err)
160→	}
161→
162→	return nil
163→}
164→
165→// FormatResumeCommand returns the command to resume a Claude Code session.
166→func (c *ClaudeCodeAgent) FormatResumeCommand(sessionID string) string {
167→	return "claude -r " + sessionID
168→}
169→
170→// Session helper methods - work on AgentSession with Claude's native JSONL data
171→
172→// GetLastUserPrompt extracts the last user prompt from the session.
173→// Requires NativeData to be populated (call ReadSession first).
174→func (c *ClaudeCodeAgent) GetLastUserPrompt(session *agent.AgentSession) string {
175→	if session == nil || len(session.NativeData) == 0 {
176→		return ""
177→	}
178→
179→	lines, err := transcript.ParseFromBytes(session.NativeData)
180→	if err != nil {
181→		return ""
182→	}
183→
184→	return ExtractLastUserPrompt(lines)
185→}
186→
187→// TruncateAtUUID returns a new session truncated at the given UUID (inclusive).
188→// This is used for rewind operations to restore transcript state.
189→// Requires NativeData to be populated.
190→func (c *ClaudeCodeAgent) TruncateAtUUID(session *agent.AgentSession, uuid string) (*agent.AgentSession, error) {
191→	if session == nil {
192→		return nil, errors.New("session is nil")
193→	}
194→
195→	if len(session.NativeData) == 0 {
196→		return nil, errors.New("session has no native data")
197→	}
198→
199→	if uuid == "" {
200→		// No truncation needed, return copy
201→		return &agent.AgentSession{
202→			SessionID:     session.SessionID,
203→			AgentName:     session.AgentName,
204→			RepoPath:      session.RepoPath,
205→			SessionRef:    session.SessionRef,
206→			StartTime:     session.StartTime,
207→			NativeData:    session.NativeData,
208→			ModifiedFiles: session.ModifiedFiles,
209→		}, nil
210→	}
211→
212→	// Parse, truncate, re-serialize
213→	lines, err := transcript.ParseFromBytes(session.NativeData)
214→	if err != nil {
215→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
216→	}
217→
218→	truncated := TruncateAtUUID(lines, uuid)
219→
220→	newData, err := SerializeTranscript(truncated)
221→	if err != nil {
222→		return nil, fmt.Errorf("failed to serialize truncated transcript: %w", err)
223→	}
224→
225→	return &agent.AgentSession{
226→		SessionID:     session.SessionID,
227→		AgentName:     session.AgentName,
228→		RepoPath:      session.RepoPath,
229→		SessionRef:    session.SessionRef,
230→		StartTime:     session.StartTime,
231→		NativeData:    newData,
232→		ModifiedFiles: ExtractModifiedFiles(truncated),
233→	}, nil
234→}
235→
236→// FindCheckpointUUID finds the UUID of the message containing the tool_result
237→// for the given tool use ID. Used for task checkpoint rewind.
238→// Returns the UUID and true if found, empty string and false otherwise.
239→func (c *ClaudeCodeAgent) FindCheckpointUUID(session *agent.AgentSession, toolUseID string) (string, bool) {
240→	if session == nil || len(session.NativeData) == 0 {
241→		return "", false
242→	}
243→
244→	lines, err := transcript.ParseFromBytes(session.NativeData)
245→	if err != nil {
246→		return "", false
247→	}
248→
249→	return FindCheckpointUUID(lines, toolUseID)
250→}
