252→// ReadSessionFromPath is a convenience method that reads a session directly from a file path.
253→// This is useful when you have the path but not a HookInput.
254→func (c *ClaudeCodeAgent) ReadSessionFromPath(transcriptPath, sessionID string) (*agent.AgentSession, error) {
255→	return c.ReadSession(&agent.HookInput{
256→		SessionID:  sessionID,
257→		SessionRef: transcriptPath,
258→	})
