 69→// ExtractPrompts extracts user prompts from the transcript starting at the given message offset.
 70→func (g *GeminiCLIAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
 71→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
 72→	if err != nil {
 73→		return nil, fmt.Errorf("failed to read transcript: %w", err)
 74→	}
 75→
 76→	t, parseErr := ParseTranscript(data)
 77→	if parseErr != nil {
 78→		return nil, fmt.Errorf("failed to parse transcript: %w", parseErr)
 79→	}
 80→
 81→	var prompts []string
 82→	for i := fromOffset; i < len(t.Messages); i++ {
 83→		msg := t.Messages[i]
 84→		if msg.Type == MessageTypeUser && msg.Content != "" {
 85→			prompts = append(prompts, msg.Content)
 86→		}
 87→	}
 88→	return prompts, nil
 89→}
