214→func (a *OpenCodeAgent) WriteSession(ctx context.Context, session *agent.AgentSession) error {
215→	if session == nil {
216→		return errors.New("nil session")
217→	}
218→	if len(session.NativeData) == 0 {
219→		return errors.New("no session data to write")
220→	}
221→
222→	// Import the session into OpenCode's database.
223→	// This enables `opencode -s <id>` for both resume and rewind.
224→	return a.importSessionIntoOpenCode(ctx, session.SessionID, session.NativeData)
225→}
226→
227→// importSessionIntoOpenCode writes the export JSON to a temp file and runs
228→// `opencode import` to restore the session into OpenCode's database.
229→// For rewind (session already exists), the session is deleted first so the
230→// reimport replaces it with the checkpoint-state messages.
231→func (a *OpenCodeAgent) importSessionIntoOpenCode(ctx context.Context, sessionID string, exportData []byte) error {
232→	// Delete existing session first so reimport replaces it cleanly.
233→	// opencode import uses ON CONFLICT DO NOTHING, so existing messages
234→	// would be skipped without this step (breaking rewind).
235→	if err := runOpenCodeSessionDelete(ctx, sessionID); err != nil {
236→		// Non-fatal: session might not exist yet (first session).
237→		// Import will still work for new sessions; only rewind of existing sessions
238→		// would have stale messages.
239→		logging.Warn(ctx, "could not delete existing opencode session",
240→			slog.String("session_id", sessionID),
241→			slog.String("error", err.Error()),
242→		)
243→	}
244→
245→	// Write export JSON to a temp file for opencode import
246→	tmpFile, err := os.CreateTemp("", "entire-opencode-export-*.json")
247→	if err != nil {
248→		return fmt.Errorf("failed to create temp file: %w", err)
249→	}
250→	defer os.Remove(tmpFile.Name())
251→
252→	if _, err := tmpFile.Write(exportData); err != nil {
253→		_ = tmpFile.Close()
254→		return fmt.Errorf("failed to write export data: %w", err)
255→	}
256→	if err := tmpFile.Close(); err != nil {
257→		return fmt.Errorf("failed to close temp file: %w", err)
258→	}
259→
260→	return runOpenCodeImport(ctx, tmpFile.Name())
261→}
262→
263→func (a *OpenCodeAgent) FormatResumeCommand(sessionID string) string {
264→	if strings.TrimSpace(sessionID) == "" {
265→		return "opencode"
266→	}
267→	return "opencode -s " + sessionID
268→}
269→
270→// nonAlphanumericRegex matches any non-alphanumeric character.
271→var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
272→
273→// SanitizePathForOpenCode converts a path to a safe directory name.
274→// Replaces any non-alphanumeric character with a dash (same approach as Claude/Gemini).
275→func SanitizePathForOpenCode(path string) string {
276→	return nonAlphanumericRegex.ReplaceAllString(path, "-")
277→}
