 129→		Short: "Disable Entire in current project",
 130→		Long: `Disable Entire integrations in the current project.
 131→
 132→By default, this command will disable Entire. Hooks will exit silently and commands will
 133→show a disabled message.
 134→
 135→To completely remove Entire integrations from this repository, use --uninstall:
 136→  - .entire/ directory (settings, logs, metadata)
 137→  - Git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)
 138→  - Session state files (.git/entire-sessions/)
 139→  - Shadow branches (entire/<hash>)
 140→  - Agent hooks`,
 141→		RunE: func(cmd *cobra.Command, _ []string) error {
 142→			ctx := cmd.Context()
 143→			if uninstall {
 144→				return runUninstall(ctx, cmd.OutOrStdout(), cmd.ErrOrStderr(), force)
 145→			}
 146→			return runDisable(ctx, cmd.OutOrStdout(), useProjectSettings)
 147→		},
 148→	}
 149→
 150→	cmd.Flags().BoolVar(&useProjectSettings, "project", false, "Update .entire/settings.json instead of .entire/settings.local.json")
 151→	cmd.Flags().BoolVar(&uninstall, "uninstall", false, "Completely remove Entire from this repository")
 152→	cmd.Flags().BoolVar(&force, "force", false, "Skip confirmation prompt (use with --uninstall)")
 153→
 154→	return cmd
 155→}
