 683→// setupEntireDirectory creates the .entire directory and gitignore.
 684→// Returns true if the directory was created, false if it already existed.
 685→func setupEntireDirectory(ctx context.Context) (bool, error) { //nolint:unparam // already present in codebase
 686→	// Get absolute path for the .entire directory
 687→	entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
 688→	if err != nil {
 689→		entireDirAbs = paths.EntireDir // Fallback to relative
 690→	}
 691→
 692→	// Check if directory already exists
 693→	created := false
 694→	if _, err := os.Stat(entireDirAbs); os.IsNotExist(err) {
 695→		created = true
 696→	}
 697→
 698→	// Create .entire directory
 699→	//nolint:gosec // G301: Project directory needs standard permissions for git
 700→	if err := os.MkdirAll(entireDirAbs, 0o755); err != nil {
 701→		return false, fmt.Errorf("failed to create .entire directory: %w", err)
 702→	}
 703→
 704→	// Create/update .gitignore with all required entries
 705→	if err := strategy.EnsureEntireGitignore(ctx); err != nil {
 706→		return false, fmt.Errorf("failed to setup .gitignore: %w", err)
 707→	}
 708→
 709→	return created, nil
 710→}
