 712→// setupGitHook installs the prepare-commit-msg hook for context trailers.
 713→func setupGitHook(ctx context.Context) error {
 714→	s, err := settings.Load(ctx)
 715→	localDev := err == nil && s.LocalDev
 716→	if _, err := strategy.InstallGitHook(ctx, false, localDev); err != nil {
 717→		return fmt.Errorf("failed to install git hook: %w", err)
 718→	}
 719→	strategy.CheckAndWarnHookManagers(ctx, os.Stderr, localDev)
 720→	return nil
 721→}
 722→
 723→// newSetupGitHookCmd creates the standalone git-hook setup command
 724→func newSetupGitHookCmd() *cobra.Command {
 725→	cmd := &cobra.Command{
 726→		Use:    "git-hook",
 727→		Short:  "Install git hook for session context trailers",
 728→		Hidden: true, // Hidden as it's mainly for testing
 729→		RunE: func(cmd *cobra.Command, _ []string) error {
 730→			return setupGitHook(cmd.Context())
 731→		},
 732→	}
 733→
 734→	return cmd
