 913→// runUninstall completely removes Entire from the repository.
 914→func runUninstall(ctx context.Context, w, errW io.Writer, force bool) error {
 915→	// Check if we're in a git repository
 916→	if _, err := paths.WorktreeRoot(ctx); err != nil {
 917→		fmt.Fprintln(errW, "Not a git repository. Nothing to uninstall.")
 918→		return NewSilentError(errors.New("not a git repository"))
 919→	}
 920→
 921→	// Gather counts for display
 922→	sessionStateCount := countSessionStates()
 923→	shadowBranchCount := countShadowBranches()
 924→	gitHooksInstalled := strategy.IsGitHookInstalled(ctx)
 925→	agentsWithInstalledHooks := GetAgentsWithHooksInstalled(ctx)
 926→	entireDirExists := checkEntireDirExists()
 927→
 928→	// Check if there's anything to uninstall
 929→	if !entireDirExists && !gitHooksInstalled && sessionStateCount == 0 &&
 930→		shadowBranchCount == 0 && len(agentsWithInstalledHooks) == 0 {
 931→		fmt.Fprintln(w, "Entire is not installed in this repository.")
 932→		return nil
 933→	}
 934→
 935→	// Show confirmation prompt unless --force
 936→	if !force {
 937→		fmt.Fprintln(w, "\nThis will completely remove Entire from this repository:")
 938→		if entireDirExists {
 939→			fmt.Fprintln(w, "  - .entire/ directory")
 940→		}
 941→		if gitHooksInstalled {
 942→			fmt.Fprintln(w, "  - Git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
 943→		}
 944→		if sessionStateCount > 0 {
 945→			fmt.Fprintf(w, "  - Session state files (%d)\n", sessionStateCount)
 946→		}
 947→		if shadowBranchCount > 0 {
 948→			fmt.Fprintf(w, "  - Shadow branches (%d)\n", shadowBranchCount)
 949→		}
 950→		if len(agentsWithInstalledHooks) > 0 {
 951→			displayNames := make([]string, 0, len(agentsWithInstalledHooks))
 952→			for _, name := range agentsWithInstalledHooks {
 953→				if ag, err := agent.Get(name); err == nil {
 954→					displayNames = append(displayNames, string(ag.Type()))
 955→				}
 956→			}
 957→			fmt.Fprintf(w, "  - Agent hooks (%s)\n", strings.Join(displayNames, ", "))
 958→		}
 959→		fmt.Fprintln(w)
 960→
 961→		var confirmed bool
 962→		form := NewAccessibleForm(
 963→			huh.NewGroup(
 964→				huh.NewConfirm().
 965→					Title("Are you sure you want to uninstall Entire?").
 966→					Affirmative("Yes, uninstall").
 967→					Negative("Cancel").
 968→					Value(&confirmed),
 969→			),
 970→		)
 971→
 972→		if err := form.Run(); err != nil {
 973→			return fmt.Errorf("confirmation cancelled: %w", err)
 974→		}
 975→
 976→		if !confirmed {
 977→			fmt.Fprintln(w, "Uninstall cancelled.")
 978→			return nil
 979→		}
 980→	}
 981→
 982→	fmt.Fprintln(w, "\nUninstalling Entire CLI...")
 983→
 984→	// 1. Remove agent hooks (lowest risk)
 985→	if err := removeAgentHooks(ctx, w); err != nil {
 986→		fmt.Fprintf(errW, "Warning: failed to remove agent hooks: %v\n", err)
 987→	}
 988→
 989→	// 2. Remove git hooks
 990→	removed, err := strategy.RemoveGitHook(ctx)
 991→	if err != nil {
 992→		fmt.Fprintf(errW, "Warning: failed to remove git hooks: %v\n", err)
 993→	} else if removed > 0 {
 994→		fmt.Fprintf(w, "  Removed git hooks (%d)\n", removed)
 995→	}
 996→
 997→	// 3. Remove session state files
 998→	statesRemoved, err := removeAllSessionStates()
 999→	if err != nil {
1000→		fmt.Fprintf(errW, "Warning: failed to remove session states: %v\n", err)
1001→	} else if statesRemoved > 0 {
1002→		fmt.Fprintf(w, "  Removed session states (%d)\n", statesRemoved)
1003→	}
1004→
1005→	// 4. Remove .entire/ directory
1006→	if err := removeEntireDirectory(); err != nil {
1007→		fmt.Fprintf(errW, "Warning: failed to remove .entire directory: %v\n", err)
1008→	} else if entireDirExists {
1009→		fmt.Fprintln(w, "  Removed .entire directory")
1010→	}
1011→
1012→	// 5. Remove shadow branches
1013→	branchesRemoved, err := removeAllShadowBranches()
1014→	if err != nil {
1015→		fmt.Fprintf(errW, "Warning: failed to remove shadow branches: %v\n", err)
1016→	} else if branchesRemoved > 0 {
1017→		fmt.Fprintf(w, "  Removed %d shadow branches\n", branchesRemoved)
1018→	}
1019→
1020→	fmt.Fprintln(w, "\nEntire CLI uninstalled successfully.")
1021→	return nil
1022→}
1023→
1024→// countSessionStates returns the number of active session state files.
1025→func countSessionStates() int {
1026→	store, err := session.NewStateStore(context.Background())
1027→	if err != nil {
1028→		return 0
1029→	}
1030→	states, err := store.List(context.Background())
1031→	if err != nil {
1032→		return 0
1033→	}
1034→	return len(states)
1035→}
1036→
1037→// countShadowBranches returns the number of shadow branches.
1038→func countShadowBranches() int {
1039→	branches, err := strategy.ListShadowBranches(context.Background())
1040→	if err != nil {
1041→		return 0
1042→	}
1043→	return len(branches)
1044→}
1045→
1046→// checkEntireDirExists checks if the .entire directory exists.
1047→func checkEntireDirExists() bool {
1048→	entireDirAbs, err := paths.AbsPath(context.Background(), paths.EntireDir)
1049→	if err != nil {
1050→		entireDirAbs = paths.EntireDir
1051→	}
1052→	_, err = os.Stat(entireDirAbs)
1053→	return err == nil
1054→}
1055→
1056→// removeAgentHooks removes hooks from all agents that support hooks.
1057→func removeAgentHooks(ctx context.Context, w io.Writer) error {
1058→	var errs []error
1059→	for _, name := range agent.List() {
1060→		ag, err := agent.Get(name)
1061→		if err != nil {
1062→			continue
1063→		}
1064→		hs, ok := ag.(agent.HookSupport)
1065→		if !ok {
1066→			continue
1067→		}
1068→		wasInstalled := hs.AreHooksInstalled(ctx)
1069→		if err := hs.UninstallHooks(ctx); err != nil {
1070→			errs = append(errs, err)
1071→		} else if wasInstalled {
1072→			fmt.Fprintf(w, "  Removed %s hooks\n", ag.Type())
1073→		}
1074→	}
1075→	return errors.Join(errs...)
1076→}
1077→
1078→// removeAllSessionStates removes all session state files and the directory.
1079→func removeAllSessionStates() (int, error) {
1080→	store, err := session.NewStateStore(context.Background())
1081→	if err != nil {
1082→		return 0, fmt.Errorf("failed to create state store: %w", err)
1083→	}
1084→
1085→	// Count states before removing
1086→	states, err := store.List(context.Background())
1087→	if err != nil {
1088→		return 0, fmt.Errorf("failed to list session states: %w", err)
1089→	}
1090→	count := len(states)
1091→
1092→	// Remove the entire directory
1093→	if err := store.RemoveAll(); err != nil {
1094→		return 0, fmt.Errorf("failed to remove session states: %w", err)
1095→	}
1096→
1097→	return count, nil
1098→}
1099→
1100→// removeEntireDirectory removes the .entire directory.
1101→func removeEntireDirectory() error {
1102→	entireDirAbs, err := paths.AbsPath(context.Background(), paths.EntireDir)
1103→	if err != nil {
1104→		entireDirAbs = paths.EntireDir
1105→	}
1106→	if err := os.RemoveAll(entireDirAbs); err != nil {
1107→		return fmt.Errorf("failed to remove .entire directory: %w", err)
1108→	}
1109→	return nil
1110→}
1111→
1112→// removeAllShadowBranches removes all shadow branches.
1113→func removeAllShadowBranches() (int, error) {
1114→	branches, err := strategy.ListShadowBranches(context.Background())
1115→	if err != nil {
1116→		return 0, fmt.Errorf("failed to list shadow branches: %w", err)
1117→	}
1118→	if len(branches) == 0 {
1119→		return 0, nil
1120→	}
1121→	deleted, _, err := strategy.DeleteShadowBranches(context.Background(), branches)
1122→	return len(deleted), err
1123→}
