 887→//   - On default branch (main/master): show all checkpoints in history (up to limit)
 888→//   - Includes both committed checkpoints (entire/checkpoints/v1) and temporary checkpoints (shadow branches)
 889→func getBranchCheckpoints(repo *git.Repository, limit int) ([]strategy.RewindPoint, error) {
 890→	store := checkpoint.NewGitStore(repo)
 891→
