// unknownSessionID is the fallback session ID used when no session ID is provided.
const unknownSessionID = "unknown"

// getAgent returns an agent by type, falling back to the default agent for empty types.
func getAgent(agentType agentpkg.AgentType) (agentpkg.Agent, error) {
	ag, err := strategy.ResolveAgentForRewind(agentType)
	if err != nil {
		return nil, fmt.Errorf("resolving agent: %w", err)
	}
	return ag, nil
}

func newRewindCmd() *cobra.Command {
	var listFlag bool
	var toFlag string
	var logsOnlyFlag bool
	var resetFlag bool

	cmd := &cobra.Command{
		Use:   "rewind",
		Short: "Browse checkpoints and rewind your session",
		Long: `Interactive command for rewinding and managing agent sessions.

This command will show you an interactive list of recent checkpoints.  You'll be
able to select one for Entire to rewind your branch state, including your code and
your agent's context.`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			// Check if Entire is disabled
			if checkDisabledGuard(cmd.OutOrStdout()) {
				return nil
			}

			ctx := cmd.Context()
			if listFlag {
				return runRewindList(ctx)
			}
			if toFlag != "" {
				return runRewindToWithOptions(ctx, toFlag, logsOnlyFlag, resetFlag)
			}
			return runRewindInteractive(ctx)
		},
	}

	cmd.Flags().BoolVar(&listFlag, "list", false, "List available rewind points (JSON output)")
	cmd.Flags().StringVar(&toFlag, "to", "", "Rewind to specific commit ID (non-interactive)")
	cmd.Flags().BoolVar(&logsOnlyFlag, "logs-only", false, "Only restore logs, don't modify working directory (for logs-only points)")
	cmd.Flags().BoolVar(&resetFlag, "reset", false, "Reset branch to commit (destructive, for logs-only points)")

	return cmd
}

func runRewindInteractive(ctx context.Context) error { //nolint:maintidx // already present in codebase
	// Get the configured strategy
	start := GetStrategy(ctx)

	// Check for uncommitted changes first
	canRewind, changeMsg, err := start.CanRewind(ctx)
	if err != nil {
		return fmt.Errorf("failed to check for uncommitted changes: %w", err)
	}
	if !canRewind {
		fmt.Println(changeMsg)
		return nil
	}

	// Get rewind points from strategy
	points, err := start.GetRewindPoints(ctx, 20)
	if err != nil {
		return fmt.Errorf("failed to find rewind points: %w", err)
	}

	if len(points) == 0 {
		fmt.Println("No rewind points found.")
		fmt.Println("Rewind points are created automatically when agent sessions end.")
		return nil
	}

	// Check if there are multiple sessions (to show session identifier)
	sessionIDs := make(map[string]bool)
	for _, p := range points {
		if p.SessionID != "" {
			sessionIDs[p.SessionID] = true
		}
	}
	hasMultipleSessions := len(sessionIDs) > 1

	// Build options for the select menu
	options := make([]huh.Option[string], 0, len(points)+1)
	for _, p := range points {
		var label string
		timestamp := p.Date.Format("2006-01-02 15:04")

		// Build session identifier for display when multiple sessions exist
		sessionLabel := ""
		if hasMultipleSessions && p.SessionPrompt != "" {
			// Show truncated prompt to identify the session
			sessionLabel = fmt.Sprintf(" [%s]", sanitizeForTerminal(p.SessionPrompt))
		}

		switch {
		case p.IsLogsOnly:
			// Committed checkpoint - show commit sha (this is the real user commit)
			shortID := p.ID
			if len(shortID) >= 7 {
				shortID = shortID[:7]
			}
			label = fmt.Sprintf("%s (%s) %s%s", shortID, timestamp, sanitizeForTerminal(p.Message), sessionLabel)
		case p.IsTaskCheckpoint:
			// Task checkpoint (uncommitted) - no sha shown
			label = fmt.Sprintf("        (%s) [Task] %s%s", timestamp, sanitizeForTerminal(p.Message), sessionLabel)
		default:
			// Shadow checkpoint (uncommitted) - no sha shown (internal commit)
			label = fmt.Sprintf("        (%s) %s%s", timestamp, sanitizeForTerminal(p.Message), sessionLabel)
		}
		options = append(options, huh.NewOption(label, p.ID))
	}
	options = append(options, huh.NewOption("Cancel", "cancel"))

	var selectedID string
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewSelect[string]().
				Title("Select a checkpoint to restore").
				Description("Your working directory will be restored to this checkpoint's state").
				Options(options...).
				Value(&selectedID),
		),
	)

	if err := form.Run(); err != nil {
		return fmt.Errorf("selection cancelled: %w", err)
	}

	if selectedID == "cancel" {
		fmt.Println("Rewind cancelled.")
		return nil
	}

	// Find the selected point
	var selectedPoint *strategy.RewindPoint
	for _, p := range points {
		if p.ID == selectedID {
			pointCopy := p
			selectedPoint = &pointCopy
			break
		}
	}

	if selectedPoint == nil {
		return errors.New("rewind point not found")
	}

	shortID := selectedPoint.ID
	if len(shortID) > 7 {
		shortID = shortID[:7]
	}

	// Show what was selected
	switch {
	case selectedPoint.IsLogsOnly:
		// Committed checkpoint - show sha
		fmt.Printf("\nSelected: %s %s\n", shortID, sanitizeForTerminal(selectedPoint.Message))
	case selectedPoint.IsTaskCheckpoint:
		// Task checkpoint - no sha
		fmt.Printf("\nSelected: [Task] %s\n", sanitizeForTerminal(selectedPoint.Message))
	default:
		// Shadow checkpoint - no sha
		fmt.Printf("\nSelected: %s\n", sanitizeForTerminal(selectedPoint.Message))
	}

	// Handle logs-only points with a sub-choice menu
	if selectedPoint.IsLogsOnly {
		return handleLogsOnlyRewindInteractive(ctx, start, *selectedPoint, shortID)
	}

	// Preview rewind to show warnings about files that will be deleted
	preview, previewErr := start.PreviewRewind(ctx, *selectedPoint)
	if previewErr == nil && preview != nil && len(preview.FilesToDelete) > 0 {
		fmt.Fprintf(os.Stderr, "\nWarning: The following untracked files will be DELETED:\n")
		for _, f := range preview.FilesToDelete {
			fmt.Fprintf(os.Stderr, "  - %s\n", f)
		}
		fmt.Fprintf(os.Stderr, "\n")
	}

	// Confirm rewind
	var confirm bool
	description := fmt.Sprintf("This will reset to: %s\nChanges after this point may be lost!", selectedPoint.Message)
	confirmForm := NewAccessibleForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title(fmt.Sprintf("Reset to %s?", shortID)).
				Description(description).
				Value(&confirm),
		),
	)

	if err := confirmForm.Run(); err != nil {
		return fmt.Errorf("confirmation cancelled: %w", err)
	}

	if !confirm {
		fmt.Println("Rewind cancelled.")
		return nil
	}

	// Resolve agent once for use throughout
	agent, err := getAgent(selectedPoint.Agent)
	if err != nil {
		return fmt.Errorf("failed to get agent: %w", err)
	}

	// Initialize logging context with agent from checkpoint
	logCtx := logging.WithComponent(ctx, "rewind")
	logCtx = logging.WithAgent(logCtx, agent.Name())

	logging.Debug(logCtx, "rewind started",
		slog.String("checkpoint_id", selectedPoint.ID),
		slog.String("session_id", selectedPoint.SessionID),
		slog.Bool("is_task_checkpoint", selectedPoint.IsTaskCheckpoint),
	)

	// Perform the rewind using strategy
	if err := start.Rewind(ctx, *selectedPoint); err != nil {
		logging.Error(logCtx, "rewind failed",
			slog.String("checkpoint_id", selectedPoint.ID),
			slog.String("error", err.Error()),
		)
		return err //nolint:wrapcheck // already present in codebase
	}

	logging.Debug(logCtx, "rewind completed",
		slog.String("checkpoint_id", selectedPoint.ID),
	)

	// Handle transcript restoration differently for task checkpoints
	var sessionID string
	var transcriptFile string

	if selectedPoint.IsTaskCheckpoint {
		// For task checkpoint: read checkpoint.json to get UUID and truncate transcript
		checkpoint, err := start.GetTaskCheckpoint(ctx, *selectedPoint)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to read task checkpoint: %v\n", err)
			return nil
		}

		sessionID = checkpoint.SessionID

		if checkpoint.CheckpointUUID != "" {
			// Truncate transcript at checkpoint UUID
			if err := restoreTaskCheckpointTranscript(ctx, start, *selectedPoint, sessionID, checkpoint.CheckpointUUID, agent); err != nil {
				fmt.Fprintf(os.Stderr, "Warning: failed to restore truncated session transcript: %v\n", err)
			} else {
				fmt.Printf("Rewound to task checkpoint. %s\n", agent.FormatResumeCommand(sessionID))
			}
			return nil
		}
	} else {
		// For session checkpoint: restore full transcript
		// Prefer SessionID from trailer (set by GetRewindPoints from Entire-Session trailer)
		// over path-based extraction which is less reliable.
		sessionID = selectedPoint.SessionID
		if sessionID == "" {
			sessionID = filepath.Base(selectedPoint.MetadataDir)
		}
		transcriptFile = filepath.Join(selectedPoint.MetadataDir, paths.TranscriptFileNameLegacy)
	}

	// Try to restore transcript using the appropriate method:
	// 1. Checkpoint storage (committed checkpoints with valid checkpoint ID)
	// 2. Shadow branch (uncommitted checkpoints with commit hash)
	// 3. Local file (active sessions)
	var restored bool
	if !selectedPoint.CheckpointID.IsEmpty() {
		// Try checkpoint storage first for committed checkpoints
		if returnedSessionID, err := restoreSessionTranscriptFromStrategy(ctx, selectedPoint.CheckpointID, sessionID, agent); err == nil {
			sessionID = returnedSessionID
			restored = true
		}
	}

	if !restored && selectedPoint.MetadataDir != "" && len(selectedPoint.ID) == 40 {
		// Try shadow branch for uncommitted checkpoints (ID is a 40-char commit hash)
		if returnedSessionID, err := restoreSessionTranscriptFromShadow(ctx, selectedPoint.ID, selectedPoint.MetadataDir, sessionID, agent); err == nil {
			sessionID = returnedSessionID
			restored = true
		}
	}

	if !restored {
		// Fall back to local file
		if err := restoreSessionTranscript(ctx, transcriptFile, sessionID, agent); err != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to restore session transcript: %v\n", err)
			fmt.Fprintf(os.Stderr, "  Source: %s\n", transcriptFile)
			fmt.Fprintf(os.Stderr, "  Session ID: %s\n", sessionID)
		}
	}

	fmt.Printf("Rewound to %s. %s\n", shortID, agent.FormatResumeCommand(sessionID))
	return nil
}

func runRewindList(ctx context.Context) error {
	start := GetStrategy(ctx)

	points, err := start.GetRewindPoints(ctx, 20)
	if err != nil {
		return fmt.Errorf("failed to find rewind points: %w", err)
	}

	// Output as JSON for programmatic use
	type jsonPoint struct {
		ID               string `json:"id"`
		Message          string `json:"message"`
		MetadataDir      string `json:"metadata_dir"`
		Date             string `json:"date"`
		IsTaskCheckpoint bool   `json:"is_task_checkpoint"`
		ToolUseID        string `json:"tool_use_id,omitempty"`
		IsLogsOnly       bool   `json:"is_logs_only"`
		CondensationID   string `json:"condensation_id,omitempty"`
		SessionID        string `json:"session_id,omitempty"`
		SessionPrompt    string `json:"session_prompt,omitempty"`
	}

	output := make([]jsonPoint, len(points))
	for i, p := range points {
		output[i] = jsonPoint{
			ID:               p.ID,
			Message:          p.Message,
			MetadataDir:      p.MetadataDir,
			Date:             p.Date.Format(time.RFC3339),
			IsTaskCheckpoint: p.IsTaskCheckpoint,
			ToolUseID:        p.ToolUseID,
			IsLogsOnly:       p.IsLogsOnly,
			CondensationID:   p.CheckpointID.String(),
			SessionID:        p.SessionID,
			SessionPrompt:    p.SessionPrompt,
		}
	}

	// Print as JSON
	data, err := jsonutil.MarshalIndentWithNewline(output, "", "  ")
	if err != nil {
		return err //nolint:wrapcheck // already present in codebase
	}
	fmt.Println(string(data))
	return nil
}

func runRewindToWithOptions(ctx context.Context, commitID string, logsOnly bool, reset bool) error {
	return runRewindToInternal(ctx, commitID, logsOnly, reset)
}

func runRewindToInternal(ctx context.Context, commitID string, logsOnly bool, reset bool) error {
	start := GetStrategy(ctx)

	// Check for uncommitted changes (skip for reset which handles this itself)
	if !reset {
		canRewind, changeMsg, err := start.CanRewind(ctx)
		if err != nil {
			return fmt.Errorf("failed to check for uncommitted changes: %w", err)
		}
		if !canRewind {
			return fmt.Errorf("%s", changeMsg)
		}
	}

	// Get rewind points
	points, err := start.GetRewindPoints(ctx, 20)
	if err != nil {
		return fmt.Errorf("failed to find rewind points: %w", err)
	}

	// Find the matching point (support both full and short commit IDs)
	var selectedPoint *strategy.RewindPoint
	for _, p := range points {
		if p.ID == commitID || (len(commitID) >= 7 && len(p.ID) >= 7 && strings.HasPrefix(p.ID, commitID)) {
			pointCopy := p
			selectedPoint = &pointCopy
			break
		}
	}

	if selectedPoint == nil {
		return fmt.Errorf("rewind point not found: %s", commitID)
	}

	// Handle reset mode (for logs-only points)
	if reset {
		return handleLogsOnlyResetNonInteractive(ctx, start, *selectedPoint)
	}

	// Handle logs-only restoration:
	// 1. For logs-only points, always use logs-only restoration
	// 2. If --logs-only flag is set, use logs-only restoration even for checkpoint points
	if selectedPoint.IsLogsOnly || logsOnly {
		return handleLogsOnlyRewindNonInteractive(ctx, start, *selectedPoint)
	}

	// Preview rewind to show warnings about files that will be deleted
	preview, previewErr := start.PreviewRewind(ctx, *selectedPoint)
	if previewErr == nil && preview != nil && len(preview.FilesToDelete) > 0 {
		fmt.Fprintf(os.Stderr, "\nWarning: The following untracked files will be DELETED:\n")
		for _, f := range preview.FilesToDelete {
			fmt.Fprintf(os.Stderr, "  - %s\n", f)
		}
		fmt.Fprintf(os.Stderr, "\n")
	}

	// Resolve agent once for use throughout
	agent, err := getAgent(selectedPoint.Agent)
	if err != nil {
		return fmt.Errorf("failed to get agent: %w", err)
	}

	// Initialize logging context with agent from checkpoint
	logCtx := logging.WithComponent(ctx, "rewind")
	logCtx = logging.WithAgent(logCtx, agent.Name())

	logging.Debug(logCtx, "rewind started",
		slog.String("checkpoint_id", selectedPoint.ID),
		slog.String("session_id", selectedPoint.SessionID),
		slog.Bool("is_task_checkpoint", selectedPoint.IsTaskCheckpoint),
	)

	// Perform the rewind
	if err := start.Rewind(ctx, *selectedPoint); err != nil {
		logging.Error(logCtx, "rewind failed",
			slog.String("checkpoint_id", selectedPoint.ID),
			slog.String("error", err.Error()),
		)
		return err //nolint:wrapcheck // already present in codebase
	}

	logging.Debug(logCtx, "rewind completed",
		slog.String("checkpoint_id", selectedPoint.ID),
	)

	// Handle transcript restoration
	var sessionID string
	var transcriptFile string

	if selectedPoint.IsTaskCheckpoint {
		checkpoint, err := start.GetTaskCheckpoint(ctx, *selectedPoint)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to read task checkpoint: %v\n", err)
			return nil
		}

		sessionID = checkpoint.SessionID

		if checkpoint.CheckpointUUID != "" {
			// Use strategy-based transcript restoration for task checkpoints
			if err := restoreTaskCheckpointTranscript(ctx, start, *selectedPoint, sessionID, checkpoint.CheckpointUUID, agent); err != nil {
				fmt.Fprintf(os.Stderr, "Warning: failed to restore truncated session transcript: %v\n", err)
			} else {
				fmt.Printf("Rewound to task checkpoint. %s\n", agent.FormatResumeCommand(sessionID))
			}
			return nil
		}
	} else {
		// Prefer SessionID from trailer over path-based extraction
		sessionID = selectedPoint.SessionID
		if sessionID == "" {
			sessionID = filepath.Base(selectedPoint.MetadataDir)
		}
		transcriptFile = filepath.Join(selectedPoint.MetadataDir, paths.TranscriptFileNameLegacy)
	}

	// Try to restore transcript using the appropriate method:
	// 1. Checkpoint storage (committed checkpoints with valid checkpoint ID)
	// 2. Shadow branch (uncommitted checkpoints with commit hash)
	// 3. Local file (active sessions)
	var restored bool
	if !selectedPoint.CheckpointID.IsEmpty() {
		// Try checkpoint storage first for committed checkpoints
		if returnedSessionID, err := restoreSessionTranscriptFromStrategy(ctx, selectedPoint.CheckpointID, sessionID, agent); err == nil {
			sessionID = returnedSessionID
			restored = true
		}
	}

	if !restored && selectedPoint.MetadataDir != "" && len(selectedPoint.ID) == 40 {
		// Try shadow branch for uncommitted checkpoints (ID is a 40-char commit hash)
		if returnedSessionID, err := restoreSessionTranscriptFromShadow(ctx, selectedPoint.ID, selectedPoint.MetadataDir, sessionID, agent); err == nil {
			sessionID = returnedSessionID
			restored = true
		}
	}

	if !restored {
		// Fall back to local file
		if err := restoreSessionTranscript(ctx, transcriptFile, sessionID, agent); err != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to restore session transcript: %v\n", err)
		}
	}

	fmt.Printf("Rewound to %s. %s\n", selectedPoint.ID[:7], agent.FormatResumeCommand(sessionID))
	return nil
}

// handleLogsOnlyRewindNonInteractive handles logs-only rewind in non-interactive mode.
// Defaults to restoring logs only (no checkout) for safety.
func handleLogsOnlyRewindNonInteractive(ctx context.Context, start strategy.Strategy, point strategy.RewindPoint) error {
	// Resolve agent once for use throughout
	agent, err := getAgent(point.Agent)
	if err != nil {
		return fmt.Errorf("failed to get agent: %w", err)
	}

	// Initialize logging context with agent from checkpoint
	logCtx := logging.WithComponent(ctx, "rewind")
	logCtx = logging.WithAgent(logCtx, agent.Name())

	logging.Debug(logCtx, "logs-only rewind started",
		slog.String("checkpoint_id", point.ID),
		slog.String("session_id", point.SessionID),
	)

	sessions, err := start.RestoreLogsOnly(ctx, point, true) // force=true for explicit rewind
	if err != nil {
		logging.Error(logCtx, "logs-only rewind failed",
			slog.String("checkpoint_id", point.ID),
			slog.String("error", err.Error()),
		)
		return fmt.Errorf("failed to restore logs: %w", err)
	}

	logging.Debug(logCtx, "logs-only rewind completed",
		slog.String("checkpoint_id", point.ID),
	)

	// Show resume commands for all sessions
	printMultiSessionResumeCommands(sessions)

	fmt.Println("Note: Working directory unchanged. Use interactive mode for full checkout.")
	return nil
}

// handleLogsOnlyResetNonInteractive handles reset in non-interactive mode.
// This performs a git reset --hard to the target commit.
func handleLogsOnlyResetNonInteractive(ctx context.Context, start strategy.Strategy, point strategy.RewindPoint) error {
	// Resolve agent once for use throughout
	agent, err := getAgent(point.Agent)
	if err != nil {
		return fmt.Errorf("failed to get agent: %w", err)
	}

	// Initialize logging context with agent from checkpoint
	logCtx := logging.WithComponent(ctx, "rewind")
	logCtx = logging.WithAgent(logCtx, agent.Name())

	logging.Debug(logCtx, "logs-only reset started",
		slog.String("checkpoint_id", point.ID),
		slog.String("session_id", point.SessionID),
	)

	// Get current HEAD before reset (for recovery message)
	currentHead, headErr := getCurrentHeadHash(ctx)
	if headErr != nil {
		currentHead = ""
	}

	// Restore logs first
	sessions, err := start.RestoreLogsOnly(ctx, point, true) // force=true for explicit rewind
	if err != nil {
		logging.Error(logCtx, "logs-only reset failed during log restoration",
			slog.String("checkpoint_id", point.ID),
			slog.String("error", err.Error()),
		)
		return fmt.Errorf("failed to restore logs: %w", err)
	}

	// Perform git reset --hard
	if err := performGitResetHard(ctx, point.ID); err != nil {
		logging.Error(logCtx, "logs-only reset failed during git reset",
			slog.String("checkpoint_id", point.ID),
			slog.String("error", err.Error()),
		)
		return fmt.Errorf("failed to reset branch: %w", err)
	}

	logging.Debug(logCtx, "logs-only reset completed",
		slog.String("checkpoint_id", point.ID),
	)

	shortID := point.ID
	if len(shortID) > 7 {
		shortID = shortID[:7]
	}

	fmt.Printf("Reset branch to %s.\n", shortID)

	// Show resume commands for all sessions
	printMultiSessionResumeCommands(sessions)

	// Show recovery instructions
	if currentHead != "" && currentHead != point.ID {
		currentShort := currentHead
		if len(currentShort) > 7 {
			currentShort = currentShort[:7]
		}
		fmt.Printf("\nTo undo this reset: git reset --hard %s\n", currentShort)
	}

	return nil
}

func restoreSessionTranscript(ctx context.Context, transcriptFile, sessionID string, agent agentpkg.Agent) error {
	sessionFile, err := resolveTranscriptPath(ctx, sessionID, agent)
	if err != nil {
		return err
	}

	// Ensure parent directory exists
	if err := os.MkdirAll(filepath.Dir(sessionFile), 0o750); err != nil {
		return fmt.Errorf("failed to create agent session directory: %w", err)
	}

	fmt.Fprintf(os.Stderr, "Copying transcript:\n  From: %s\n  To: %s\n", transcriptFile, sessionFile)
	if err := copyFile(transcriptFile, sessionFile); err != nil {
		return fmt.Errorf("failed to copy transcript: %w", err)
	}

	return nil
}

// restoreSessionTranscriptFromStrategy restores a session transcript from checkpoint storage.
// This is used for strategies that store transcripts in git branches rather than local files.
// Returns the session ID that was actually used (may differ from input if checkpoint provides one).
func restoreSessionTranscriptFromStrategy(ctx context.Context, cpID id.CheckpointID, sessionID string, agent agentpkg.Agent) (string, error) {
	// Get transcript content from checkpoint storage
	content, returnedSessionID, err := checkpoint.LookupSessionLog(ctx, cpID)
	if err != nil {
		return "", fmt.Errorf("failed to get session log: %w", err)
	}

	// Use session ID returned from checkpoint if available
	// Otherwise fall back to the passed-in sessionID
	if returnedSessionID != "" {
		sessionID = returnedSessionID
	}

	sessionFile, err := resolveTranscriptPath(ctx, sessionID, agent)
	if err != nil {
		return "", err
	}
	if err := os.MkdirAll(filepath.Dir(sessionFile), 0o750); err != nil {
		return "", fmt.Errorf("failed to create agent session directory: %w", err)
	}
	agentSession := &agentpkg.AgentSession{
		SessionID:  sessionID,
		AgentName:  agent.Name(),
		SessionRef: sessionFile,
		NativeData: content,
	}
	if err := agent.WriteSession(ctx, agentSession); err != nil {
		return "", fmt.Errorf("failed to write session: %w", err)
	}
	return sessionID, nil
}

// restoreSessionTranscriptFromShadow restores a session transcript from a shadow branch commit.
// This is used for uncommitted checkpoints where the transcript is stored in the shadow branch tree.
func restoreSessionTranscriptFromShadow(ctx context.Context, commitHash, metadataDir, sessionID string, agent agentpkg.Agent) (string, error) {
	// Open repository
	repo, err := git.PlainOpenWithOptions(".", &git.PlainOpenOptions{DetectDotGit: true})
	if err != nil {
		return "", fmt.Errorf("failed to open repository: %w", err)
	}

	// Parse commit hash
	hash := plumbing.NewHash(commitHash)
	if hash.IsZero() {
		return "", fmt.Errorf("invalid commit hash: %s", commitHash)
	}

	// Get transcript from shadow branch commit tree
	store := checkpoint.NewGitStore(repo)
	content, err := store.GetTranscriptFromCommit(ctx, hash, metadataDir, agent.Type())
	if err != nil {
		return "", fmt.Errorf("failed to get transcript from shadow branch: %w", err)
	}

	sessionFile, err := resolveTranscriptPath(ctx, sessionID, agent)
	if err != nil {
		return "", err
	}
	if err := os.MkdirAll(filepath.Dir(sessionFile), 0o750); err != nil {
		return "", fmt.Errorf("failed to create agent session directory: %w", err)
	}
	agentSession := &agentpkg.AgentSession{
		SessionID:  sessionID,
		AgentName:  agent.Name(),
		SessionRef: sessionFile,
		NativeData: content,
	}
	if err := agent.WriteSession(ctx, agentSession); err != nil {
		return "", fmt.Errorf("failed to write session: %w", err)
	}
	return sessionID, nil
}

// restoreTaskCheckpointTranscript restores a truncated transcript for a task checkpoint.
// Uses GetTaskCheckpointTranscript to fetch the transcript from the strategy.
//
// NOTE: The transcript parsing/truncation/writing pipeline (transcript.ParseFromBytes,
// TruncateTranscriptAtUUID, writeTranscript) assumes Claude's JSONL format.
// This is acceptable because task checkpoints are currently only created by Claude Code's
// PostToolUse hook. If other agents gain sub-agent support, this will need a
// format-aware refactor (agent-specific parsing, truncation, and serialization).
func restoreTaskCheckpointTranscript(ctx context.Context, strat strategy.Strategy, point strategy.RewindPoint, sessionID, checkpointUUID string, agent agentpkg.Agent) error {
	// Get transcript content from strategy
	content, err := strat.GetTaskCheckpointTranscript(ctx, point)
	if err != nil {
		return fmt.Errorf("failed to get task checkpoint transcript: %w", err)
	}

	// Parse the transcript
	parsed, err := transcript.ParseFromBytes(content)
	if err != nil {
		return fmt.Errorf("failed to parse transcript: %w", err)
	}

	// Truncate at checkpoint UUID
	truncated := TruncateTranscriptAtUUID(parsed, checkpointUUID)

	sessionFile, err := resolveTranscriptPath(ctx, sessionID, agent)
	if err != nil {
		return err
	}

	// Ensure parent directory exists
	if err := os.MkdirAll(filepath.Dir(sessionFile), 0o750); err != nil {
		return fmt.Errorf("failed to create agent session directory: %w", err)
	}

	fmt.Fprintf(os.Stderr, "Writing truncated transcript to: %s\n", sessionFile)

	if err := writeTranscript(sessionFile, truncated); err != nil {
		return fmt.Errorf("failed to write truncated transcript: %w", err)
	}

	return nil
}

// handleLogsOnlyRewindInteractive handles rewind for logs-only points with a sub-choice menu.
func handleLogsOnlyRewindInteractive(ctx context.Context, start strategy.Strategy, point strategy.RewindPoint, shortID string) error {
	var action string

	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewSelect[string]().
				Title("Logs-only point: "+shortID).
				Description("This commit has session logs but no checkpoint state. Choose an action:").
				Options(
					huh.NewOption("Restore logs only (keep current files)", "logs"),
					huh.NewOption("Checkout commit (detached HEAD, for viewing)", "checkout"),
					huh.NewOption("Reset branch to this commit (destructive!)", "reset"),
					huh.NewOption("Cancel", "cancel"),
				).
				Value(&action),
		),
	)

	if err := form.Run(); err != nil {
		return fmt.Errorf("action selection cancelled: %w", err)
	}

	switch action {
	case "logs":
		return handleLogsOnlyRestore(ctx, start, point)
	case "checkout":
		return handleLogsOnlyCheckout(ctx, start, point, shortID)
	case "reset":
		return handleLogsOnlyReset(ctx, start, point, shortID)
	case "cancel":
		fmt.Println("Rewind cancelled.")
		return nil
	}

	return nil
}

// handleLogsOnlyRestore restores only the session logs without changing files.
func handleLogsOnlyRestore(ctx context.Context, start strategy.Strategy, point strategy.RewindPoint) error {
	// Resolve agent once for use throughout
	agent, err := getAgent(point.Agent)
	if err != nil {
		return fmt.Errorf("failed to get agent: %w", err)
	}

	// Initialize logging context with agent from checkpoint
	logCtx := logging.WithComponent(ctx, "rewind")
	logCtx = logging.WithAgent(logCtx, agent.Name())

	logging.Debug(logCtx, "logs-only restore started",
		slog.String("checkpoint_id", point.ID),
		slog.String("session_id", point.SessionID),
	)

	// Restore logs
	sessions, err := start.RestoreLogsOnly(ctx, point, true) // force=true for explicit rewind
	if err != nil {
		logging.Error(logCtx, "logs-only restore failed",
			slog.String("checkpoint_id", point.ID),
			slog.String("error", err.Error()),
		)
		return fmt.Errorf("failed to restore logs: %w", err)
	}

	logging.Debug(logCtx, "logs-only restore completed",
		slog.String("checkpoint_id", point.ID),
	)

	// Show resume commands for all sessions
	fmt.Println("Restored session logs.")
	printMultiSessionResumeCommands(sessions)
	return nil
}

// handleLogsOnlyCheckout restores logs and checks out the commit (detached HEAD).
func handleLogsOnlyCheckout(ctx context.Context, start strategy.Strategy, point strategy.RewindPoint, shortID string) error {
	// Resolve agent once for use throughout
	agent, err := getAgent(point.Agent)
	if err != nil {
		return fmt.Errorf("failed to get agent: %w", err)
	}

	// Initialize logging context with agent from checkpoint
	logCtx := logging.WithComponent(ctx, "rewind")
	logCtx = logging.WithAgent(logCtx, agent.Name())

	logging.Debug(logCtx, "logs-only checkout started",
		slog.String("checkpoint_id", point.ID),
		slog.String("session_id", point.SessionID),
	)

	sessions, err := start.RestoreLogsOnly(ctx, point, true) // force=true for explicit rewind
	if err != nil {
		logging.Error(logCtx, "logs-only checkout failed during log restoration",
			slog.String("checkpoint_id", point.ID),
			slog.String("error", err.Error()),
		)
		return fmt.Errorf("failed to restore logs: %w", err)
	}

	// Show warning about detached HEAD
	var confirm bool
	confirmForm := NewAccessibleForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title("Create detached HEAD?").
				Description("This will checkout the commit directly. You'll be in 'detached HEAD' state.\nAny uncommitted changes will be lost!").
				Value(&confirm),
		),
	)

	if err := confirmForm.Run(); err != nil {
		return fmt.Errorf("confirmation cancelled: %w", err)
	}

	if !confirm {
		fmt.Println("Checkout cancelled. Session logs were still restored.")
		printMultiSessionResumeCommands(sessions)
		return nil
	}

	// Perform git checkout
	if err := CheckoutBranch(ctx, point.ID); err != nil {
		logging.Error(logCtx, "logs-only checkout failed during git checkout",
			slog.String("checkpoint_id", point.ID),
			slog.String("error", err.Error()),
		)
		return fmt.Errorf("failed to checkout commit: %w", err)
	}

	logging.Debug(logCtx, "logs-only checkout completed",
		slog.String("checkpoint_id", point.ID),
	)

	fmt.Printf("Checked out %s (detached HEAD).\n", shortID)
	printMultiSessionResumeCommands(sessions)
	return nil
}

// handleLogsOnlyReset restores logs and resets the branch to the commit (destructive).
func handleLogsOnlyReset(ctx context.Context, start strategy.Strategy, point strategy.RewindPoint, shortID string) error {
	// Resolve agent once for use throughout
	agent, agentErr := getAgent(point.Agent)
	if agentErr != nil {
		return fmt.Errorf("failed to get agent: %w", agentErr)
	}

	// Initialize logging context with agent from checkpoint
	logCtx := logging.WithComponent(ctx, "rewind")
	logCtx = logging.WithAgent(logCtx, agent.Name())

	logging.Debug(logCtx, "logs-only reset (interactive) started",
		slog.String("checkpoint_id", point.ID),
		slog.String("session_id", point.SessionID),
	)

	sessions, restoreErr := start.RestoreLogsOnly(ctx, point, true) // force=true for explicit rewind
	if restoreErr != nil {
		logging.Error(logCtx, "logs-only reset failed during log restoration",
			slog.String("checkpoint_id", point.ID),
			slog.String("error", restoreErr.Error()),
		)
		return fmt.Errorf("failed to restore logs: %w", restoreErr)
	}

	// Get current HEAD before reset (for recovery message)
	currentHead, err := getCurrentHeadHash(ctx)
	if err != nil {
		// Non-fatal - just won't show recovery message
		currentHead = ""
	}

	// Get detailed uncommitted changes warning from strategy
	var uncommittedWarning string
	if _, warn, err := start.CanRewind(ctx); err == nil {
		uncommittedWarning = warn
	}

	// Check for safety issues
	warnings, err := checkResetSafety(ctx, point.ID, uncommittedWarning)
	if err != nil {
		return fmt.Errorf("failed to check reset safety: %w", err)
	}

	// Build confirmation message based on warnings
	var confirmTitle, confirmDesc string
	if len(warnings) > 0 {
		confirmTitle = "⚠️  Reset branch with warnings?"
		confirmDesc = "WARNING - the following issues were detected:\n" +
			strings.Join(warnings, "\n") +
			"\n\nThis will move your branch to " + shortID + " and DISCARD commits after it!"
	} else {
		confirmTitle = "Reset branch to " + shortID + "?"
		confirmDesc = "This will move your branch pointer to this commit.\nCommits after this point will be orphaned (but recoverable via reflog)."
	}

	var confirm bool
	confirmForm := NewAccessibleForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title(confirmTitle).
				Description(confirmDesc).
				Value(&confirm),
		),
	)

	if err := confirmForm.Run(); err != nil {
		return fmt.Errorf("confirmation cancelled: %w", err)
	}

	if !confirm {
		fmt.Println("Reset cancelled. Session logs were still restored.")
		printMultiSessionResumeCommands(sessions)
		return nil
	}

	// Perform git reset --hard
	if err := performGitResetHard(ctx, point.ID); err != nil {
		logging.Error(logCtx, "logs-only reset failed during git reset",
			slog.String("checkpoint_id", point.ID),
			slog.String("error", err.Error()),
		)
		return fmt.Errorf("failed to reset branch: %w", err)
	}

	logging.Debug(logCtx, "logs-only reset (interactive) completed",
		slog.String("checkpoint_id", point.ID),
	)

	fmt.Printf("Reset branch to %s.\n", shortID)
	printMultiSessionResumeCommands(sessions)

	// Show recovery instructions
	if currentHead != "" && currentHead != point.ID {
		currentShort := currentHead
		if len(currentShort) > 7 {
			currentShort = currentShort[:7]
		}
		fmt.Printf("\nTo undo this reset: git reset --hard %s\n", currentShort)
	}

	return nil
}

// getCurrentHeadHash returns the current HEAD commit hash.
func getCurrentHeadHash(ctx context.Context) (string, error) {
	repo, err := openRepository(ctx)
	if err != nil {
		return "", err
	}

	head, err := repo.Head()
	if err != nil {
		return "", fmt.Errorf("failed to get HEAD: %w", err)
	}

	return head.Hash().String(), nil
}

// checkResetSafety checks for potential issues before a git reset --hard.
// Returns a list of warning messages (empty if safe to proceed without warnings).
// If uncommittedChangesWarning is provided, it will be used instead of a generic warning.
func checkResetSafety(ctx context.Context, targetCommitHash string, uncommittedChangesWarning string) ([]string, error) {
	var warnings []string

	repo, err := openRepository(ctx)
	if err != nil {
		return nil, err
	}

	// Check for uncommitted changes
	if uncommittedChangesWarning != "" {
		// Use the detailed warning from strategy's CanRewind()
		warnings = append(warnings, uncommittedChangesWarning)
	} else {
		// Fall back to generic check
		worktree, err := repo.Worktree()
		if err != nil {
			return nil, fmt.Errorf("failed to get worktree: %w", err)
		}

		status, err := worktree.Status()
		if err != nil {
			return nil, fmt.Errorf("failed to get status: %w", err)
		}

		if !status.IsClean() {
			warnings = append(warnings, "• You have uncommitted changes that will be LOST")
		}
	}

	// Check if current HEAD is ahead of target (we'd be discarding commits)
	head, err := repo.Head()
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD: %w", err)
	}

	targetHash := plumbing.NewHash(targetCommitHash)

	// Count commits between target and HEAD
	commitsAhead, err := countCommitsBetween(repo, targetHash, head.Hash())
	if err != nil {
		// Non-fatal - just can't show commit count
		commitsAhead = -1
	}

	if commitsAhead > 0 {
		warnings = append(warnings, fmt.Sprintf("• %d commit(s) after this point will be orphaned", commitsAhead))
	}

	return warnings, nil
}

// countCommitsBetween counts commits between ancestor and descendant.
// Returns 0 if ancestor == descendant, -1 on error.
func countCommitsBetween(repo *git.Repository, ancestor, descendant plumbing.Hash) (int, error) {
	if ancestor == descendant {
		return 0, nil
	}

	// Walk from descendant back to ancestor
	count := 0
	current := descendant

	for count < 1000 { // Safety limit
		if current == ancestor {
			return count, nil
		}

		commit, err := repo.CommitObject(current)
		if err != nil {
			return -1, fmt.Errorf("failed to get commit: %w", err)
		}

		if commit.NumParents() == 0 {
			// Reached root without finding ancestor - ancestor not in history
			return -1, nil
		}

		count++
		current = commit.ParentHashes[0] // Follow first parent
	}

	return -1, nil
}

// performGitResetHard performs a git reset --hard to the specified commit.
// Uses the git CLI instead of go-git because go-git's HardReset incorrectly
// deletes untracked directories (like .entire/) even when they're in .gitignore.
func performGitResetHard(ctx context.Context, commitHash string) error {
	if strings.HasPrefix(commitHash, "-") {
		return fmt.Errorf("reset failed: invalid commit hash %q", commitHash)
	}
	cmd := exec.CommandContext(ctx, "git", "reset", "--hard", commitHash)
	if output, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("reset failed: %s: %w", strings.TrimSpace(string(output)), err)
	}
	return nil
}

// sanitizeForTerminal removes or replaces characters that cause rendering issues
// in terminal UI components. This includes emojis with skin-tone modifiers and
// other multi-codepoint characters that confuse width calculations.
func sanitizeForTerminal(s string) string {
	var result strings.Builder
	result.Grow(len(s))

	for _, r := range s {
		// Skip emoji skin tone modifiers (U+1F3FB to U+1F3FF)
		if r >= 0x1F3FB && r <= 0x1F3FF {
			continue
		}
		// Skip zero-width joiners used in emoji sequences
		if r == 0x200D {
			continue
		}
		// Skip variation selectors (U+FE00 to U+FE0F)
		if r >= 0xFE00 && r <= 0xFE0F {
			continue
		}
		// Keep printable characters and common whitespace
		if unicode.IsPrint(r) || r == '\t' || r == '\n' {
			result.WriteRune(r)
		}
	}

	return result.String()
}

// printMultiSessionResumeCommands prints resume commands for restored sessions.
// Each session may have a different agent, so per-session agent resolution is used.
func printMultiSessionResumeCommands(sessions []strategy.RestoredSession) {
	if len(sessions) == 0 {
		return
	}

	if len(sessions) > 1 {
		fmt.Printf("\nRestored %d sessions. Resume with:\n", len(sessions))
	}

	for i, sess := range sessions {
		ag, err := strategy.ResolveAgentForRewind(sess.Agent)
		if err != nil {
			fmt.Fprintf(os.Stderr, "  Warning: could not resolve agent %q for session %s, skipping\n", sess.Agent, sess.SessionID)
			continue
		}

		cmd := ag.FormatResumeCommand(sess.SessionID)

		if len(sessions) > 1 {
			// Add "(most recent)" label to the last session
			if i == len(sessions)-1 {
				if sess.Prompt != "" {
					fmt.Printf("  %s  # %s (most recent)\n", cmd, sess.Prompt)
				} else {
					fmt.Printf("  %s  # (most recent)\n", cmd)
				}
			} else {
				if sess.Prompt != "" {
					fmt.Printf("  %s  # %s\n", cmd, sess.Prompt)
				} else {
					fmt.Printf("  %s\n", cmd)
				}
			}
		} else {
			if sess.Prompt != "" {
				fmt.Printf("%s  # %s\n", cmd, sess.Prompt)
			} else {
				fmt.Printf("%s\n", cmd)
			}
		}
	}
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"sort"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/entireio/cli/cmd/entire/cli/trailers"

	"github.com/charmbracelet/huh"
	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/object"
	"github.com/spf13/cobra"
)

func newResumeCmd() *cobra.Command {
	var force bool

	cmd := &cobra.Command{
		Use:   "resume <branch>",
		Short: "Switch to a branch and resume its session",
		Long: `Switch to a local branch and resume the agent session from its last commit.

This command:
1. Checks out the specified branch
2. Finds the session ID from commits unique to this branch (not on main)
3. Restores the session log if it doesn't exist locally
4. Shows the command to resume the session

If the branch doesn't exist locally but exists on origin, you'll be prompted
to fetch it.

If newer commits without checkpoints exist on the branch (e.g., after merging main
or cherry-picking from elsewhere), this operation will reset your Git status to the
most recent commit with a checkpoint.  You'll be prompted to confirm resuming in this case.`,
		Args: cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			if checkDisabledGuard(cmd.OutOrStdout()) {
				return nil
			}
			return runResume(cmd.Context(), args[0], force)
		},
	}

	cmd.Flags().BoolVarP(&force, "force", "f", false, "Resume from older checkpoint without confirmation")

	return cmd
}

func runResume(ctx context.Context, branchName string, force bool) error {
	// Check if we're already on this branch
	currentBranch, err := GetCurrentBranch(ctx)
	if err == nil && currentBranch == branchName {
		// Already on the branch, skip checkout
		return resumeFromCurrentBranch(ctx, branchName, force)
	}

	// Check if branch exists locally
	exists, err := BranchExistsLocally(ctx, branchName)
	if err != nil {
		return fmt.Errorf("failed to check branch: %w", err)
	}

	if !exists {
		// Branch doesn't exist locally, check if it exists on remote
		remoteExists, err := BranchExistsOnRemote(ctx, branchName)
		if err != nil {
			return fmt.Errorf("failed to check remote branch: %w", err)
		}

		if !remoteExists {
			return fmt.Errorf("branch '%s' not found locally or on origin", branchName)
		}

		// Ask user if they want to fetch from remote
		shouldFetch, err := promptFetchFromRemote(branchName)
		if err != nil {
			return err
		}
		if !shouldFetch {
			return nil
		}

		// Fetch and checkout the remote branch
		fmt.Fprintf(os.Stderr, "Fetching branch '%s' from origin...\n", branchName)
		if err := FetchAndCheckoutRemoteBranch(ctx, branchName); err != nil {
			fmt.Fprintf(os.Stderr, "Failed to checkout branch: %v\n", err)
			return NewSilentError(errors.New("failed to checkout branch"))
		}
		fmt.Fprintf(os.Stderr, "Switched to branch '%s'\n", branchName)
	} else {
		// Branch exists locally, check for uncommitted changes before checkout
		hasChanges, err := HasUncommittedChanges(ctx)
		if err != nil {
			return fmt.Errorf("failed to check for uncommitted changes: %w", err)
		}
		if hasChanges {
			return errors.New("you have uncommitted changes. Please commit or stash them first")
		}

		// Checkout the branch
		if err := CheckoutBranch(ctx, branchName); err != nil {
			fmt.Fprintf(os.Stderr, "Failed to checkout branch: %v\n", err)
			return NewSilentError(errors.New("failed to checkout branch"))
		}
		fmt.Fprintf(os.Stderr, "Switched to branch '%s'\n", branchName)
	}

	return resumeFromCurrentBranch(ctx, branchName, force)
}

func resumeFromCurrentBranch(ctx context.Context, branchName string, force bool) error {
	repo, err := openRepository(ctx)
	if err != nil {
		return fmt.Errorf("not a git repository: %w", err)
	}

	// Find a commit with an Entire-Checkpoint trailer, looking at branch-only commits
	result, err := findBranchCheckpoint(repo, branchName)
	if err != nil {
		return err
	}
	if result.checkpointID.IsEmpty() {
		fmt.Fprintf(os.Stderr, "No Entire checkpoint found on branch '%s'\n", branchName)
		return nil
	}

	// If there are newer commits without checkpoints, ask for confirmation.
	// Merge commits (e.g., from merging main) don't count as "work" and are skipped silently.
	if result.newerCommitsExist && !force {
		fmt.Fprintf(os.Stderr, "Found checkpoint in an older commit.\n")
		fmt.Fprintf(os.Stderr, "There are %d newer commit(s) on this branch without checkpoints.\n", result.newerCommitCount)
		fmt.Fprintf(os.Stderr, "Checkpoint from: %s %s\n\n", result.commitHash[:7], firstLine(result.commitMessage))

		shouldResume, err := promptResumeFromOlderCheckpoint()
		if err != nil {
			return err
		}
		if !shouldResume {
			fmt.Fprintf(os.Stderr, "Resume cancelled.\n")
			return nil
		}
	}

	checkpointID := result.checkpointID

	// Get metadata branch tree for lookups
	metadataTree, err := strategy.GetMetadataBranchTree(repo)
	if err != nil {
		// No local metadata branch, check if remote has it
		return checkRemoteMetadata(ctx, repo, checkpointID)
	}

	// Look up metadata from sharded path
	metadata, err := strategy.ReadCheckpointMetadata(metadataTree, checkpointID.Path())
	if err != nil {
		// Checkpoint exists in commit but no local metadata - check remote
		return checkRemoteMetadata(ctx, repo, checkpointID)
	}

	return resumeSession(ctx, metadata.SessionID, checkpointID, force)
}

// branchCheckpointResult contains the result of searching for a checkpoint on a branch.
type branchCheckpointResult struct {
	checkpointID      id.CheckpointID
	commitHash        string
	commitMessage     string
	newerCommitsExist bool // true if there are branch-only commits (not merge commits) without checkpoints
	newerCommitCount  int  // count of branch-only commits without checkpoints
}

// findBranchCheckpoint finds the most recent commit with an Entire-Checkpoint trailer
// among commits that are unique to this branch (not reachable from the default branch).
// This handles the case where main has been merged into the feature branch.
func findBranchCheckpoint(repo *git.Repository, branchName string) (*branchCheckpointResult, error) {
	result := &branchCheckpointResult{}

	// Get HEAD commit
	head, err := repo.Head()
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD: %w", err)
	}

	headCommit, err := repo.CommitObject(head.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
	}

	// First, check if HEAD itself has a checkpoint (most common case)
	if cpID, found := trailers.ParseCheckpoint(headCommit.Message); found {
		result.checkpointID = cpID
		result.commitHash = head.Hash().String()
		result.commitMessage = headCommit.Message
		result.newerCommitsExist = false
		return result, nil
	}

	// HEAD doesn't have a checkpoint - find branch-only commits
	// Get the default branch name
	defaultBranch := getDefaultBranchFromRemote(repo)
	if defaultBranch == "" {
		// Fallback: try common names
		for _, name := range []string{"main", "master"} {
			if _, err := repo.Reference(plumbing.NewBranchReferenceName(name), true); err == nil {
				defaultBranch = name
				break
			}
		}
	}

	// If we can't find a default branch, or we're on it, just walk all commits
	if defaultBranch == "" || defaultBranch == branchName {
		return findCheckpointInHistory(headCommit, nil), nil
	}

	// Get the default branch reference
	defaultRef, err := repo.Reference(plumbing.NewBranchReferenceName(defaultBranch), true)
	if err != nil {
		// Default branch doesn't exist locally, fall back to walking all commits
		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
	}

	defaultCommit, err := repo.CommitObject(defaultRef.Hash())
	if err != nil {
		// Can't get default commit, fall back to walking all commits
		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
	}

	// Find merge base
	mergeBase, err := headCommit.MergeBase(defaultCommit)
	if err != nil || len(mergeBase) == 0 {
		// No common ancestor, fall back to walking all commits
		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
	}

	// Walk from HEAD to merge base, looking for checkpoint
	return findCheckpointInHistory(headCommit, &mergeBase[0].Hash), nil
}

// findCheckpointInHistory walks commit history from start looking for a checkpoint trailer.
// If stopAt is provided, stops when reaching that commit (exclusive).
// Returns the first checkpoint found and info about commits between HEAD and the checkpoint.
// It distinguishes between merge commits (bringing in other branches) and regular commits
// (actual branch work) to avoid false warnings after merging main.
func findCheckpointInHistory(start *object.Commit, stopAt *plumbing.Hash) *branchCheckpointResult {
	result := &branchCheckpointResult{}
	branchWorkCommits := 0 // Regular commits without checkpoints (actual work)
	const maxCommits = 100 // Limit search depth
	totalChecked := 0

	current := start
	for current != nil && totalChecked < maxCommits {
		// Stop if we've reached the boundary
		if stopAt != nil && current.Hash == *stopAt {
			break
		}

		// Check for checkpoint trailer
		if cpID, found := trailers.ParseCheckpoint(current.Message); found {
			result.checkpointID = cpID
			result.commitHash = current.Hash.String()
			result.commitMessage = current.Message
			// Only warn about branch work commits, not merge commits
			result.newerCommitsExist = branchWorkCommits > 0
			result.newerCommitCount = branchWorkCommits
			return result
		}

		// Only count regular commits (not merge commits) as "branch work"
		if current.NumParents() <= 1 {
			branchWorkCommits++
		}

		totalChecked++

		// Move to parent (first parent for merge commits - follows the main line)
		if current.NumParents() == 0 {
			break
		}
		parent, err := current.Parent(0)
		if err != nil {
			// Can't get parent, treat as end of history
			break
		}
		current = parent
	}

	// No checkpoint found
	return result
}

// promptResumeFromOlderCheckpoint asks the user if they want to resume from an older checkpoint.
func promptResumeFromOlderCheckpoint() (bool, error) {
	var confirmed bool

	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title("Resume from this older checkpoint?").
				Value(&confirmed),
		),
	)

	if err := form.Run(); err != nil {
		if errors.Is(err, huh.ErrUserAborted) {
			return false, nil
		}
		return false, fmt.Errorf("failed to get confirmation: %w", err)
	}

	return confirmed, nil
}

// checkRemoteMetadata checks if checkpoint metadata exists on origin/entire/checkpoints/v1
// and automatically fetches it if available.
func checkRemoteMetadata(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID) error {
	// Try to get remote metadata branch tree
	remoteTree, err := strategy.GetRemoteMetadataBranchTree(repo)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
		fmt.Fprintf(os.Stderr, "The entire/checkpoints/v1 branch may not exist locally or on the remote.\n")
		return nil //nolint:nilerr // Informational message, not a fatal error
	}

	// Check if the checkpoint exists on the remote
	metadata, err := strategy.ReadCheckpointMetadata(remoteTree, checkpointID.Path())
	if err != nil {
		fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
		return nil //nolint:nilerr // Informational message, not a fatal error
	}

	// Metadata exists on remote but not locally - fetch it automatically
	fmt.Fprintf(os.Stderr, "Fetching session metadata from origin...\n")
	if err := FetchMetadataBranch(ctx); err != nil {
		fmt.Fprintf(os.Stderr, "Failed to fetch metadata: %v\n", err)
		fmt.Fprintf(os.Stderr, "You can try manually: git fetch origin entire/checkpoints/v1:entire/checkpoints/v1\n")
		return NewSilentError(errors.New("failed to fetch metadata"))
	}

	// Now resume the session with the fetched metadata
	return resumeSession(ctx, metadata.SessionID, checkpointID, false)
}

// resumeSession restores and displays the resume command for a specific session.
// For multi-session checkpoints, restores ALL sessions and shows commands for each.
// If force is false, prompts for confirmation when local logs have newer timestamps.
func resumeSession(ctx context.Context, sessionID string, checkpointID id.CheckpointID, force bool) error {
	// Read checkpoint metadata first to get agent type (matching rewind pattern)
	repo, err := openRepository(ctx)
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}

	metadataTree, err := strategy.GetMetadataBranchTree(repo)
	if err != nil {
		return fmt.Errorf("failed to get metadata branch: %w", err)
	}

	metadata, err := strategy.ReadCheckpointMetadata(metadataTree, checkpointID.Path())
	if err != nil {
		return fmt.Errorf("failed to read checkpoint metadata: %w", err)
	}

	// Resolve agent from checkpoint metadata (same as rewind)
	ag, err := strategy.ResolveAgentForRewind(metadata.Agent)
	if err != nil {
		return fmt.Errorf("failed to resolve agent: %w", err)
	}

	// Initialize logging context with agent
	logCtx := logging.WithAgent(logging.WithComponent(ctx, "resume"), ag.Name())

	logging.Debug(logCtx, "resume session started",
		slog.String("checkpoint_id", checkpointID.String()),
		slog.String("session_id", sessionID),
	)

	// Get worktree root for session directory lookup
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return fmt.Errorf("failed to get worktree root: %w", err)
	}

	sessionDir, err := ag.GetSessionDir(repoRoot)
	if err != nil {
		return fmt.Errorf("failed to determine session directory: %w", err)
	}

	// Create directory if it doesn't exist
	if err := os.MkdirAll(sessionDir, 0o700); err != nil {
		return fmt.Errorf("failed to create session directory: %w", err)
	}

	// Get strategy and restore sessions using full checkpoint data
	strat := GetStrategy(ctx)

	// Use RestoreLogsOnly via LogsOnlyRestorer interface for multi-session support
	// Create a logs-only rewind point with Agent populated (same as rewind)
	point := strategy.RewindPoint{
		IsLogsOnly:   true,
		CheckpointID: checkpointID,
		Agent:        metadata.Agent,
	}

	sessions, restoreErr := strat.RestoreLogsOnly(ctx, point, force)
	if restoreErr != nil || len(sessions) == 0 {
		// Fall back to single-session restore (e.g., old checkpoints without agent metadata)
		return resumeSingleSession(ctx, ag, sessionID, checkpointID, repoRoot, force)
	}

	// Sort sessions by CreatedAt so the most recent is last (for display).
	// This fixes ordering when subdirectory index doesn't reflect activity order.
	sort.Slice(sessions, func(i, j int) bool {
		return sessions[i].CreatedAt.Before(sessions[j].CreatedAt)
	})

	logging.Debug(logCtx, "resume session completed",
		slog.String("checkpoint_id", checkpointID.String()),
		slog.Int("session_count", len(sessions)),
	)

	// Print per-session resume commands using returned sessions
	if len(sessions) > 1 {
		fmt.Fprintf(os.Stderr, "\nRestored %d sessions. To continue, run:\n", len(sessions))
	} else if len(sessions) == 1 {
		fmt.Fprintf(os.Stderr, "Session: %s\n", sessions[0].SessionID)
		fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
	}
	for i, sess := range sessions {
		sessionAgent, err := strategy.ResolveAgentForRewind(sess.Agent)
		if err != nil {
			return fmt.Errorf("failed to resolve agent for session %s: %w", sess.SessionID, err)
		}
		cmd := sessionAgent.FormatResumeCommand(sess.SessionID)

		if len(sessions) > 1 {
			if i == len(sessions)-1 {
				if sess.Prompt != "" {
					fmt.Fprintf(os.Stderr, "  %s  # %s (most recent)\n", cmd, sess.Prompt)
				} else {
					fmt.Fprintf(os.Stderr, "  %s  # (most recent)\n", cmd)
				}
			} else {
				if sess.Prompt != "" {
					fmt.Fprintf(os.Stderr, "  %s  # %s\n", cmd, sess.Prompt)
				} else {
					fmt.Fprintf(os.Stderr, "  %s\n", cmd)
				}
			}
		} else {
			if sess.Prompt != "" {
				fmt.Fprintf(os.Stderr, "  %s  # %s\n", cmd, sess.Prompt)
			} else {
				fmt.Fprintf(os.Stderr, "  %s\n", cmd)
			}
		}
	}

	return nil
}

// resumeSingleSession restores a single session (fallback when multi-session restore fails).
// Always overwrites existing session logs to ensure consistency with checkpoint state.
// If force is false, prompts for confirmation when local log has newer timestamps.
func resumeSingleSession(ctx context.Context, ag agent.Agent, sessionID string, checkpointID id.CheckpointID, repoRoot string, force bool) error {
	sessionLogPath, err := resolveTranscriptPath(sessionID, ag)
	if err != nil {
		return fmt.Errorf("failed to resolve transcript path: %w", err)
	}

	if checkpointID.IsEmpty() {
		logging.Debug(ctx, "resume session: empty checkpoint ID",
			slog.String("checkpoint_id", checkpointID.String()),
		)
		fmt.Fprintf(os.Stderr, "Session '%s' found in commit trailer but session log not available\n", sessionID)
		fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
		fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(sessionID))
		return nil
	}

	logContent, _, err := checkpoint.LookupSessionLog(ctx, checkpointID)
	if err != nil {
		if errors.Is(err, checkpoint.ErrCheckpointNotFound) || errors.Is(err, checkpoint.ErrNoTranscript) {
			logging.Debug(ctx, "resume session completed (no metadata)",
				slog.String("checkpoint_id", checkpointID.String()),
				slog.String("session_id", sessionID),
			)
			fmt.Fprintf(os.Stderr, "Session '%s' found in commit trailer but session log not available\n", sessionID)
			fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
			fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(sessionID))
			return nil
		}
		logging.Error(ctx, "resume session failed",
			slog.String("checkpoint_id", checkpointID.String()),
			slog.String("session_id", sessionID),
			slog.String("error", err.Error()),
		)
		return fmt.Errorf("failed to get session log: %w", err)
	}

	// Check if local file has newer timestamps than checkpoint
	if !force {
		localTime := paths.GetLastTimestampFromFile(sessionLogPath)
		checkpointTime := paths.GetLastTimestampFromBytes(logContent)
		status := strategy.ClassifyTimestamps(localTime, checkpointTime)

		if status == strategy.StatusLocalNewer {
			sessions := []strategy.SessionRestoreInfo{{
				SessionID:      sessionID,
				Status:         status,
				LocalTime:      localTime,
				CheckpointTime: checkpointTime,
			}}
			shouldOverwrite, promptErr := strategy.PromptOverwriteNewerLogs(sessions)
			if promptErr != nil {
				return fmt.Errorf("failed to get confirmation: %w", promptErr)
			}
			if !shouldOverwrite {
				fmt.Fprintf(os.Stderr, "Resume cancelled. Local session log preserved.\n")
				return nil
			}
		}
	}

	// Ensure parent directory exists
	if err := os.MkdirAll(filepath.Dir(sessionLogPath), 0o750); err != nil {
		return fmt.Errorf("failed to create session directory: %w", err)
	}

	agentSession := &agent.AgentSession{
		SessionID:  sessionID,
		AgentName:  ag.Name(),
		RepoPath:   repoRoot,
		SessionRef: sessionLogPath,
		NativeData: logContent,
	}

	// Write the session using the agent's WriteSession method
	if err := ag.WriteSession(ctx, agentSession); err != nil {
		logging.Error(ctx, "resume session failed during write",
			slog.String("checkpoint_id", checkpointID.String()),
			slog.String("session_id", sessionID),
			slog.String("error", err.Error()),
		)
		return fmt.Errorf("failed to write session: %w", err)
	}

	logging.Debug(ctx, "resume session completed",
		slog.String("checkpoint_id", checkpointID.String()),
		slog.String("session_id", sessionID),
	)

	fmt.Fprintf(os.Stderr, "Session restored to: %s\n", sessionLogPath)
	fmt.Fprintf(os.Stderr, "Session: %s\n", sessionID)
	fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
	fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(sessionID))

	return nil
}

func promptFetchFromRemote(branchName string) (bool, error) {
	var confirmed bool

	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title(fmt.Sprintf("Branch '%s' not found locally. Fetch from origin?", branchName)).
				Value(&confirmed),
		),
	)

	if err := form.Run(); err != nil {
		if errors.Is(err, huh.ErrUserAborted) {
			return false, nil
		}
		return false, fmt.Errorf("failed to get confirmation: %w", err)
	}

	return confirmed, nil
}

// firstLine returns the first line of a string
func firstLine(s string) string {
	for i, c := range s {
		if c == '\n' {
			return s[:i]
		}
	}
	return s
}

package cli

import (
	"bufio"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	agentpkg "github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/claudecode"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/textutil"
	"github.com/entireio/cli/cmd/entire/cli/transcript"
)

// Transcript message type constants - aliases to transcript package for local use.
const (
	transcriptTypeUser      = transcript.TypeUser
	transcriptTypeAssistant = transcript.TypeAssistant
	contentTypeText         = transcript.ContentTypeText
	contentTypeToolUse      = transcript.ContentTypeToolUse
)

// PromptResponsePair represents a user prompt and the assistant's responses.
// Used for extracting all interactions from a transcript.
type PromptResponsePair struct {
	Prompt    string
	Responses []string // Multiple responses can occur between tool calls
	Files     []string
}

// ExtractAllPromptResponses extracts all user prompt and assistant response pairs from a transcript.
// Returns pairs in chronological order (oldest first).
// Each pair contains the user's prompt, assistant's text response, and files modified.
func ExtractAllPromptResponses(transcript []transcriptLine) []PromptResponsePair {
	var pairs []PromptResponsePair

	// Find all user prompts (messages with string content, not tool results)
	var userIndices []int
	for i, line := range transcript {
		if line.Type == transcriptTypeUser {
			var msg userMessage
			if err := json.Unmarshal(line.Message, &msg); err != nil {
				continue
			}
			// Only count messages with string content (real user prompts)
			if _, ok := msg.Content.(string); ok {
				userIndices = append(userIndices, i)
			} else if arr, ok := msg.Content.([]interface{}); ok {
				// Check if array has text blocks (also a real user prompt)
				for _, item := range arr {
					if m, ok := item.(map[string]interface{}); ok {
						if m["type"] == contentTypeText {
							userIndices = append(userIndices, i)
							break
						}
					}
				}
			}
		}
	}

	// For each user prompt, extract the prompt text, following assistant response, and files
	for idx, userIdx := range userIndices {
		// Determine the range for this prompt's conversation
		endIdx := len(transcript)
		if idx < len(userIndices)-1 {
			endIdx = userIndices[idx+1]
		}

		// Extract prompt text
		prompt := extractUserPromptAt(transcript, userIdx)
		if prompt == "" {
			continue
		}

		// Extract assistant responses and files from this range
		slice := transcript[userIdx:endIdx]
		responses := extractAssistantResponses(slice)
		files := extractModifiedFiles(slice)

		pairs = append(pairs, PromptResponsePair{
			Prompt:    prompt,
			Responses: responses,
			Files:     files,
		})
	}

	return pairs
}

// extractUserPromptAt extracts the user prompt at the given index.
// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
func extractUserPromptAt(lines []transcriptLine, idx int) string {
	if idx >= len(lines) || lines[idx].Type != transcriptTypeUser {
		return ""
	}

	return transcript.ExtractUserContent(lines[idx].Message)
}

// extractAssistantResponses collects all assistant text blocks from the given transcript slice.
// A single prompt can trigger multiple assistant responses interspersed with tool calls.
func extractAssistantResponses(transcript []transcriptLine) []string {
	var texts []string
	for _, line := range transcript {
		if line.Type == transcriptTypeAssistant {
			var msg assistantMessage
			if err := json.Unmarshal(line.Message, &msg); err != nil {
				continue
			}

			for _, block := range msg.Content {
				if block.Type == contentTypeText && block.Text != "" {
					texts = append(texts, block.Text)
				}
			}
		}
	}
	return texts
}

// extractUserPrompts extracts all user messages from the transcript in order.
// Only considers messages with string content (not tool results).
// IDE-injected context tags (like <ide_opened_file>) are stripped from the results.
func extractUserPrompts(transcript []transcriptLine) []string {
	var prompts []string
	for i := range transcript {
		if transcript[i].Type != transcriptTypeUser {
			continue
		}
		var msg userMessage
		if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
			continue
		}

		// Handle string content
		if str, ok := msg.Content.(string); ok {
			prompts = append(prompts, textutil.StripIDEContextTags(str))
			continue
		}

		// Handle array content (only if it contains text blocks)
		if arr, ok := msg.Content.([]interface{}); ok {
			var texts []string
			for _, item := range arr {
				if m, ok := item.(map[string]interface{}); ok {
					if m["type"] == contentTypeText {
						if text, ok := m["text"].(string); ok {
							texts = append(texts, text)
						}
					}
				}
			}
			if len(texts) > 0 {
				prompts = append(prompts, textutil.StripIDEContextTags(strings.Join(texts, "\n\n")))
			}
		}
	}
	return prompts
}

// extractLastUserPrompt extracts the last user message from the transcript.
// Only considers messages with string content (not tool results).
// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
func extractLastUserPrompt(transcript []transcriptLine) string {
	prompts := extractUserPrompts(transcript)
	if len(prompts) == 0 {
		return ""
	}
	return prompts[len(prompts)-1]
}

// findLastUserUUID finds the UUID of the last user message (that has string content)
func findLastUserUUID(transcript []transcriptLine) string {
	for i := len(transcript) - 1; i >= 0; i-- {
		if transcript[i].Type == transcriptTypeUser {
			var msg userMessage
			if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
				continue
			}
			// Only count messages with string content (not tool results)
			if _, ok := msg.Content.(string); ok {
				return transcript[i].UUID
			}
		}
	}
	return ""
}

// filterTranscriptAfterUUID returns transcript lines after the given UUID
func filterTranscriptAfterUUID(transcript []transcriptLine, uuid string) []transcriptLine {
	if uuid == "" {
		return transcript
	}

	foundIndex := -1
	for i, line := range transcript {
		if line.UUID == uuid {
			foundIndex = i
			break
		}
	}

	if foundIndex == -1 || foundIndex == len(transcript)-1 {
		return transcript
	}

	return transcript[foundIndex+1:]
}

// extractModifiedFiles extracts the list of files modified by tool calls
func extractModifiedFiles(transcript []transcriptLine) []string {
	fileSet := make(map[string]bool)
	var files []string

	for _, line := range transcript {
		if line.Type == transcriptTypeAssistant {
			var msg assistantMessage
			if err := json.Unmarshal(line.Message, &msg); err != nil {
				continue
			}

			for _, block := range msg.Content {
				if block.Type == contentTypeToolUse {
					isModifyTool := false
					for _, name := range claudecode.FileModificationTools {
						if block.Name == name {
							isModifyTool = true
							break
						}
					}

					if isModifyTool {
						var input toolInput
						if err := json.Unmarshal(block.Input, &input); err != nil {
							continue
						}

						file := input.FilePath
						if file == "" {
							file = input.NotebookPath
						}

						if file != "" && !fileSet[file] {
							fileSet[file] = true
							files = append(files, file)
						}
					}
				}
			}
		}
	}

	return files
}

// resolveTranscriptPath determines the correct file path for an agent's session transcript.
// Computes the path dynamically from the current repo location for cross-machine portability.
func resolveTranscriptPath(sessionID string, agent agentpkg.Agent) (string, error) {
	repoRoot, err := paths.WorktreeRoot(context.Background())
	if err != nil {
		return "", fmt.Errorf("failed to get worktree root: %w", err)
	}

	sessionDir, err := agent.GetSessionDir(repoRoot)
	if err != nil {
		return "", fmt.Errorf("failed to get agent session directory: %w", err)
	}
	return agent.ResolveSessionFile(sessionDir, sessionID), nil
}

// AgentTranscriptPath returns the path to a subagent's transcript file.
// Subagent transcripts are stored as agent-{agentId}.jsonl in the same directory
// as the main transcript.
func AgentTranscriptPath(transcriptDir, agentID string) string {
	return filepath.Join(transcriptDir, fmt.Sprintf("agent-%s.jsonl", agentID))
}

// toolResultBlock represents a tool_result in a user message
type toolResultBlock struct {
	Type      string `json:"type"`
	ToolUseID string `json:"tool_use_id"`
}

// userMessageWithToolResults represents a user message that may contain tool results
type userMessageWithToolResults struct {
	Content []toolResultBlock `json:"content"`
}

// FindCheckpointUUID finds the UUID of the message containing the tool_result
// for the given tool_use_id. This is used to find the checkpoint point for
// transcript truncation when rewinding to a task.
// Returns the UUID and true if found, empty string and false otherwise.
func FindCheckpointUUID(transcript []transcriptLine, toolUseID string) (string, bool) {
	for _, line := range transcript {
		if line.Type != transcriptTypeUser {
			continue
		}

		var msg userMessageWithToolResults
		if err := json.Unmarshal(line.Message, &msg); err != nil {
			continue
		}

		for _, block := range msg.Content {
			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
				return line.UUID, true
			}
		}
	}
	return "", false
}

// TruncateTranscriptAtUUID returns transcript lines up to and including the
// line with the given UUID. If the UUID is not found or is empty, returns
// the entire transcript.
//
//nolint:revive // Exported for testing purposes
func TruncateTranscriptAtUUID(transcript []transcriptLine, uuid string) []transcriptLine {
	if uuid == "" {
		return transcript
	}

	for i, line := range transcript {
		if line.UUID == uuid {
			return transcript[:i+1]
		}
	}

	// UUID not found, return full transcript
	return transcript
}

// writeTranscript writes transcript lines to a file in JSONL format.
func writeTranscript(path string, transcript []transcriptLine) error {
	file, err := os.Create(path) //nolint:gosec // Writing to controlled git metadata path
	if err != nil {
		return fmt.Errorf("failed to create file: %w", err)
	}
	defer func() { _ = file.Close() }()

	for _, line := range transcript {
		data, err := json.Marshal(line)
		if err != nil {
			return fmt.Errorf("failed to marshal line: %w", err)
		}
		if _, err := file.Write(data); err != nil {
			return fmt.Errorf("failed to write line: %w", err)
		}
		if _, err := file.WriteString("\n"); err != nil {
			return fmt.Errorf("failed to write newline: %w", err)
		}
	}

	return nil
}

// TranscriptPosition contains the position information for a transcript file.
type TranscriptPosition struct {
	LastUUID  string // Last non-empty UUID (from user/assistant messages)
	LineCount int    // Total number of lines
}

// GetTranscriptPosition reads a transcript file and returns the last UUID and line count.
// Returns empty position if file doesn't exist or is empty.
// Only considers UUIDs from actual messages (user/assistant), not summary rows which use leafUuid.
func GetTranscriptPosition(path string) (TranscriptPosition, error) {
	if path == "" {
		return TranscriptPosition{}, nil
	}

	file, err := os.Open(path) //nolint:gosec // Reading from controlled transcript path
	if err != nil {
		if os.IsNotExist(err) {
			return TranscriptPosition{}, nil
		}
		return TranscriptPosition{}, fmt.Errorf("failed to open transcript: %w", err)
	}
	defer func() { _ = file.Close() }()

	var pos TranscriptPosition
	reader := bufio.NewReader(file)

	for {
		lineBytes, err := reader.ReadBytes('\n')
		if err != nil && err != io.EOF {
			return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
		}

		if len(lineBytes) == 0 {
			if err == io.EOF {
				break
			}
			continue
		}

		pos.LineCount++

		// Parse line to extract UUID (only from user/assistant messages, not summaries)
		var line transcriptLine
		if err := json.Unmarshal(lineBytes, &line); err == nil {
			if line.UUID != "" {
				pos.LastUUID = line.UUID
			}
		}

		if err == io.EOF {
			break
		}
	}

	return pos, nil
}

