	} else if changes.Deleted[0] != "tracked.txt" {
		t.Errorf("DetectFileChanges(context.Background(),nil) Deleted[0] = %v, want tracked.txt", changes.Deleted[0])
	}
}

func TestDetectFileChanges_NewAndDeletedFiles(t *testing.T) {
