func TestScopeTranscriptForCheckpoint_SlicesTranscript(t *testing.T) {
	// Transcript with 5 lines - prompts 1, 2, 3 with their responses
	fullTranscript := []byte(`{"type":"user","uuid":"u1","message":{"content":"prompt 1"}}
